// v3da01_minimal_api_groups / ex1 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public record Dock(string Id, string Name, int Capacity);

public record Bike(int Id, string DockId, string State);

public record DockDto(string Id, string Name, int Capacity)
{
    public static DockDto From(Dock dock) => new(dock.Id, dock.Name, dock.Capacity);
}

public record BikeDto(int Id, string DockId, string State)
{
    public static BikeDto From(Bike bike) => new(bike.Id, bike.DockId, bike.State);
}

public static class V3DA01Depot
{
    public static readonly List<Dock> Docks =
    [
        new("kings", "Kings Cross", 30),
        new("wharf", "Canary Wharf", 24),
        new("mile", "Mile End", 12),
    ];

    public static readonly List<Bike> Bikes =
    [
        new(1, "kings", "ready"),
        new(2, "kings", "hired"),
        new(3, "wharf", "ready"),
        new(4, "mile", "repair"),
        new(5, "wharf", "ready"),
    ];

    public static Dock? FindDock(string id) => Docks.FirstOrDefault(d => d.Id == id);

    public static Bike? FindBike(int id) => Bikes.FirstOrDefault(b => b.Id == id);
}

public class Ex1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        // The prefix and the tag are stated once. Everything mapped into the
        // group inherits both, including endpoints mapped after this line.
        var docks = app.MapGroup("/v3da01/docks").WithTags("v3da01");

        docks.MapGet("/", ListDocks);
        docks.MapGet("/{id}", GetDock);
    }

    private static IResult ListDocks() =>
        TypedResults.Ok(V3DA01Depot.Docks
            .OrderBy(d => d.Id, StringComparer.Ordinal)
            .Select(DockDto.From)
            .ToList());

    private static IResult GetDock(string id)
    {
        var dock = V3DA01Depot.FindDock(id);

        return dock is null
            ? TypedResults.NotFound()
            : TypedResults.Ok(DockDto.From(dock));
    }
}

