// v3da01_minimal_api_groups / ex2 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public class Ex2 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var bikes = app.MapGroup("/v3da01/bikes").WithTags("v3da01");

        // Declared "wrong" on purpose: precedence is computed from the segment
        // kinds, so the literal below still beats both parameters.
        bikes.MapGet("/{id:int}", GetBike);
        bikes.MapGet("/{dockId:alpha}", GetByDock);
        bikes.MapGet("/available", GetAvailable);

        bikes.MapGet("/by-id", GetByQueryId);
    }

    private static IResult GetBike(int id)
    {
        var bike = V3DA01Depot.FindBike(id);

        return bike is null
            ? TypedResults.NotFound()
            : TypedResults.Ok(BikeDto.From(bike));
    }

    private static IResult GetByDock(string dockId)
    {
        if (V3DA01Depot.FindDock(dockId) is null)
        {
            return TypedResults.NotFound();
        }

        return TypedResults.Ok(V3DA01Depot.Bikes
            .Where(b => b.DockId == dockId)
            .OrderBy(b => b.Id)
            .Select(BikeDto.From)
            .ToList());
    }

    private static IResult GetAvailable() =>
        TypedResults.Ok(V3DA01Depot.Bikes
            .Where(b => b.State == "ready")
            .OrderBy(b => b.Id)
            .Select(BikeDto.From)
            .ToList());

    // Same lookup, but the identifier arrives unconstrained - so a malformed
    // one can be reported as a malformed one instead of vanishing into a 404.
    private static IResult GetByQueryId(string? id)
    {
        if (!int.TryParse(id, out var parsed))
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["id"] = ["Not an integer."],
            });
        }

        var bike = V3DA01Depot.FindBike(parsed);

        return bike is null
            ? TypedResults.NotFound()
            : TypedResults.Ok(BikeDto.From(bike));
    }
}

exercises.hints:
## Hint 1

An endpoint filter has the same shape as middleware — do something, `await next`,
do something — but a different signature: it takes an
`EndpointFilterInvocationContext` and returns `ValueTask<object?>`. The `object?`
is the handler's return value on its way out.

## Hint 2

The shape, for a different concern:

    group.AddEndpointFilter(async (context, next) =>
    {
        context.HttpContext.Response.Headers["X-Tenant"] = "acme";
        var result = await next(context);
        context.HttpContext.Response.Headers["X-Size"] =
            result is IValueHttpResult v ? v.Value?.ToString() : "none";
        return result;
    });

## Hint 3

`context.HttpContext` is the same `HttpContext` middleware sees. Set the first
header, `var result = await next(context);`, set the second from
`result?.GetType().Name`, and return `result` — returning anything else replaces
the response. The decision left to you: group filter or endpoint filter? Both
pass here; say out loud why before you choose.

