// v3da01_minimal_api_groups / ex3 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public record DockCount(int Count);

public class Ex3 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var audit = app.MapGroup("/v3da01/audit")
            .WithTags("v3da01")
            .AddEndpointFilter(async (context, next) =>
            {
                // Before: the request has been bound, the handler has not run.
                context.HttpContext.Response.Headers["X-Depot-Filter"] = "v3da01";

                var result = await next(context);

                // After: the handler returned an IResult object, and nothing has
                // been written to the response yet - so headers are still open.
                context.HttpContext.Response.Headers["X-Depot-Result"] =
                    result?.GetType().Name ?? "null";

                return result;
            });

        audit.MapGet("/docks", CountDocks);
    }

    private static Ok<DockCount> CountDocks() =>
        TypedResults.Ok(new DockCount(V3DA01Depot.Docks.Count));
}

