using Microsoft.Extensions.Primitives;

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public class Ex4 : IEndpointMapper
{
    public const string Key = "v3da01-key";

    public static int HandlerCalls;

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var keyed = app.MapGroup("/v3da01/keyed")
            .WithTags("v3da01")
            .AddEndpointFilter(async (context, next) =>
            {
                var headers = context.HttpContext.Request.Headers;

                if (!headers.TryGetValue("X-Depot-Key", out var supplied)
                    || StringValues.IsNullOrEmpty(supplied))
                {
                    // No call to next: the handler is never entered.
                    return TypedResults.Problem(title: "Missing depot key", statusCode: 400);
                }

                if (!string.Equals(supplied.ToString(), Key, StringComparison.Ordinal))
                {
                    return TypedResults.Problem(title: "Unknown depot key", statusCode: 403);
                }

                return await next(context);
            });

        keyed.MapPost("/checks", RunCheck);

        // Mapped on the application, not the group - so the key filter, which is
        // a group convention, never applies to it.
        app.MapGet("/v3da01/keyed/calls", () => TypedResults.Ok(new { calls = HandlerCalls }))
            .WithTags("v3da01");
    }

    private static IResult RunCheck()
    {
        Interlocked.Increment(ref HandlerCalls);

        return TypedResults.Ok(new { ok = true });
    }
}

