// v3da01_minimal_api_groups / ex5 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public class Ex5 : IEndpointMapper
{
    private const string ItemsKey = "v3da01";

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var order = app.MapGroup("/v3da01/order")
            .WithTags("v3da01")
            .AddEndpointFilter(async (context, next) =>
            {
                var trace = Trace(context.HttpContext);
                trace.Add("g1>");

                var result = await next(context);

                trace.Add("g1<");
                context.HttpContext.Response.Headers["X-Filter-Trace"] = string.Join(",", trace);

                return result;
            });

        // Two endpoint filters on the same builder: the first added is the outer
        // one, and both sit inside the group filter above.
        order.MapGet("/trace", Handle)
            .AddEndpointFilter(Stamp("e1"))
            .AddEndpointFilter(Stamp("e2"));

        order.MapGet("/plain", Handle);
    }

    private static Func<EndpointFilterInvocationContext, EndpointFilterDelegate, ValueTask<object?>>
        Stamp(string name) =>
        async (context, next) =>
        {
            var trace = Trace(context.HttpContext);
            trace.Add($"{name}>");

            var result = await next(context);

            trace.Add($"{name}<");

            return result;
        };

    private static IResult Handle(HttpContext http)
    {
        Trace(http).Add("handler");

        return TypedResults.Ok(new { ok = true });
    }

    private static List<string> Trace(HttpContext http) =>
        (List<string>)(http.Items[ItemsKey] ??= new List<string>());
}

exercises.hints:
## Hint 1

By the time a filter runs, the JSON body is already a `RideRequest` object. That
is the whole reason to validate here rather than in middleware: no re-reading of
the stream, no second deserialisation, no buffering.

## Hint 2

The class form, for a different payload:

    public class TripFilter(IOptions<TripLimits> limits) : IEndpointFilter
    {
        public async ValueTask<object?> InvokeAsync(
            EndpointFilterInvocationContext context, EndpointFilterDelegate next)
        {
            var trip = context.Arguments.OfType<TripRequest>().First();
            if (trip.Km > limits.Value.MaxKm) return TypedResults.BadRequest();
            return await next(context);
        }
    }

`AddEndpointFilter<T>()` builds `T` through `ActivatorUtilities`, so constructor
parameters come from the container.

## Hint 3

Three guards in the order the prompt fixes, then `return await next(context);`.
The handler itself is three lines. The decision left to you: `V3DA01Limits` as a
plain singleton or wrapped in `IOptions<T>` — both are registerable, and only one
of them lets the value come from `appsettings.json` later.

