// v3da01_minimal_api_groups / ex6 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public record RideRequest(int BikeId, int Minutes);

public class V3DA01Limits
{
    public int MaxMinutes { get; set; } = 120;
}

public class RideRequestFilter(V3DA01Limits limits) : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        // Found by type: the handler's parameter order is not this filter's
        // business, and it will change one day without telling anyone.
        var body = context.Arguments.OfType<RideRequest>().First();

        if (body.Minutes < 1 || body.Minutes > limits.MaxMinutes)
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["minutes"] = [$"Between 1 and {limits.MaxMinutes} minutes."],
            });
        }

        var bike = V3DA01Depot.FindBike(body.BikeId);
        if (bike is null)
        {
            return TypedResults.NotFound();
        }

        if (bike.State != "ready")
        {
            return TypedResults.Problem(title: "Bike not available", statusCode: 409);
        }

        return await next(context);
    }
}

public class Ex6Services : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton(new V3DA01Limits { MaxMinutes = 120 });
    }
}

public class Ex6 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3da01/rides", StartRide)
            .AddEndpointFilter<RideRequestFilter>()
            .WithTags("v3da01");
    }

    private static IResult StartRide(RideRequest body, CancellationToken cancellation) =>
        TypedResults.Created(
            $"/v3da01/rides/{body.BikeId}",
            new { bikeId = body.BikeId, minutes = body.Minutes });
}

