// v3da01_minimal_api_groups / ex7 - reference solution (author only, used by `dojo verify`).

using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public class Ex7 : IEndpointMapper
{
    private const string Pattern = "/v3da01/typed/bikes/{id}";

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var typed = app.MapGroup("/v3da01/typed").WithTags("v3da01");

        typed.MapGet("/bikes/{id}", GetBike);
        typed.MapGet("/metadata", GetMetadata);
    }

    // The union is the documentation: no Produces calls anywhere in this file.
    private static Results<Ok<BikeDto>, NotFound, ValidationProblem> GetBike(string id)
    {
        if (!int.TryParse(id, out var parsed))
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["id"] = ["Not an integer."],
            });
        }

        var bike = V3DA01Depot.FindBike(parsed);

        return bike is null
            ? TypedResults.NotFound()
            : TypedResults.Ok(BikeDto.From(bike));
    }

    private static Ok<object> GetMetadata(EndpointDataSource endpoints)
    {
        var endpoint = endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .First(e => e.RoutePattern.RawText == Pattern);

        var statusCodes = endpoint.Metadata
            .GetOrderedMetadata<IProducesResponseTypeMetadata>()
            .Select(m => m.StatusCode)
            .Distinct()
            .Order()
            .ToList();

        return TypedResults.Ok<object>(new { statusCodes });
    }
}

exercises.hints:
## Hint 1

Two lambdas, nested. The outer one runs once per endpoint when the application is
built; the inner one runs once per request. Everything expensive belongs in the
outer one.

## Hint 2

The shape, deciding on a different parameter type:

    group.AddEndpointFilterFactory((context, next) =>
    {
        var index = Array.FindIndex(
            context.MethodInfo.GetParameters(),
            p => p.ParameterType == typeof(TripRequest));

        if (index < 0) return next;

        return async invocation =>
        {
            var trip = invocation.GetArgument<TripRequest>(index);
            if (trip.Km <= 0) return TypedResults.BadRequest();
            return await next(invocation);
        };
    });

## Hint 3

`return next;` is the "do not wrap" answer — it hands back the delegate you were
given, so the built chain for that endpoint contains one less link. The decision
left to you: set `X-Ride-Checked` before or after `await next(invocation)`? Both
reach the client, and one of them also gets set on the 400 path. The prompt says
the header is present on both, so pick accordingly.

