// v3da01_minimal_api_groups / ex8 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public class Ex8 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var factory = app.MapGroup("/v3da01/factory").WithTags("v3da01");

        factory.AddEndpointFilterFactory((context, next) =>
        {
            // Runs once per endpoint, while the app is being built.
            var index = Array.FindIndex(
                context.MethodInfo.GetParameters(),
                p => p.ParameterType == typeof(RideRequest));

            if (index < 0)
            {
                // No filter is added to this endpoint at all.
                return next;
            }

            // Runs once per request, with the index already known.
            return async invocation =>
            {
                invocation.HttpContext.Response.Headers["X-Ride-Checked"] = "true";

                var body = invocation.GetArgument<RideRequest>(index);
                if (body.Minutes < 1)
                {
                    return TypedResults.ValidationProblem(new Dictionary<string, string[]>
                    {
                        ["minutes"] = ["Must be at least 1."],
                    });
                }

                return await next(invocation);
            };
        });

        factory.MapPost("/rides", StartRide);
        factory.MapGet("/rides/{id:int}", GetRide);
    }

    private static IResult StartRide(RideRequest body) =>
        TypedResults.Created(
            $"/v3da01/factory/rides/{body.BikeId}",
            new { bikeId = body.BikeId, minutes = body.Minutes });

    private static IResult GetRide(int id) =>
        TypedResults.Ok(new { bikeId = id, minutes = 30 });
}

exercises.hints:
## Hint 1

Three concerns, three layers, and the order is decided by cost and by blast
radius: the cheapest, most global refusal outermost. A caller with no depot key
should never reach code that inspects idempotency keys.

## Hint 2

Storing and replaying, sketched for a different payload:

    if (Store.TryGetValue(key, out var previous))
    {
        invocation.HttpContext.Response.Headers["X-Replay"] = "true";
        return TypedResults.Ok(previous);
    }

    var result = await next(invocation);
    if (result is Created<QuoteDto> created && created.Value is { } value)
    {
        Store[key] = value;
    }
    return result;

Note the pattern match: only the success shape is stored.

## Hint 3

`Created<RideDto>` exposes `.Value`, which is the `RideDto` you stored. Replaying
it as `TypedResults.Ok(stored)` is a 200 with the same JSON — the resource was
created once, and the second call did not create anything, so 201 would be a lie.
The decision left to you: a `ConcurrentDictionary` or a plain one? Say what the
gate does and what production does, and pick for the harder of the two.

