// v3da01_minimal_api_groups / challenge - reference solution (author only, used by `dojo verify`).

using System.Collections.Concurrent;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.Extensions.Primitives;

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public record RideDto(int RideId, int BikeId, int Minutes);

public class Challenge : IEndpointMapper
{
    private static readonly ConcurrentDictionary<string, RideDto> Replays = new();
    private static int _nextRideId;

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        // Outer: the cheapest and most global refusal.
        var ops = app.MapGroup("/v3da01/ops")
            .WithTags("v3da01")
            .AddEndpointFilter(async (context, next) =>
            {
                var headers = context.HttpContext.Request.Headers;

                if (!headers.TryGetValue("X-Depot-Key", out var key)
                    || StringValues.IsNullOrEmpty(key))
                {
                    return TypedResults.Problem(title: "Missing depot key", statusCode: 400);
                }

                if (!string.Equals(key.ToString(), Ex4.Key, StringComparison.Ordinal))
                {
                    return TypedResults.Problem(title: "Unknown depot key", statusCode: 403);
                }

                return await next(context);
            });

        var rides = ops.MapGroup("/rides");

        rides.AddEndpointFilterFactory((context, next) =>
        {
            var takesRide = context.MethodInfo.GetParameters()
                .Any(p => p.ParameterType == typeof(RideRequest));

            if (!takesRide)
            {
                return next;
            }

            return async invocation =>
            {
                var headers = invocation.HttpContext.Request.Headers;

                if (!headers.TryGetValue("X-Idempotency-Key", out var raw)
                    || StringValues.IsNullOrEmpty(raw))
                {
                    return TypedResults.Problem(
                        title: "Missing idempotency key", statusCode: 400);
                }

                var key = raw.ToString();

                if (Replays.TryGetValue(key, out var previous))
                {
                    invocation.HttpContext.Response.Headers["X-Idempotent-Replay"] = "true";

                    // The resource was created by the first call, not this one.
                    return TypedResults.Ok(previous);
                }

                var result = await next(invocation);

                // Only a success is worth remembering: a client that fixes a bad
                // payload and retries the same key deserves the fixed behaviour.
                if (result is Created<RideDto> created && created.Value is { } value)
                {
                    Replays[key] = value;
                }

                return result;
            };
        });

        rides.MapPost("/", StartRide);
        rides.MapGet("/count", () => TypedResults.Ok(new { count = Replays.Values.Count }));
    }

    private static Results<Created<RideDto>, ValidationProblem, ProblemHttpResult> StartRide(
        RideRequest body)
    {
        if (body.Minutes < 1 || body.Minutes > 120)
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["minutes"] = ["Between 1 and 120 minutes."],
            });
        }

        if (V3DA01Depot.FindBike(body.BikeId) is null)
        {
            return TypedResults.Problem(title: "No such bike", statusCode: 404);
        }

        var ride = new RideDto(Interlocked.Increment(ref _nextRideId), body.BikeId, body.Minutes);

        return TypedResults.Created($"/v3da01/ops/rides/{ride.RideId}", ride);
    }
}

