// v3da01_minimal_api_groups / review1 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA01_MinimalApis;

public class Review1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3da01/review/docks/{dockId}/bikes", Park)
            .AddEndpointFilter(async (context, next) =>
            {
                try
                {
                    return await next(context);
                }
                catch (UnknownDockException ex)
                {
                    return TypedResults.Problem(
                        title: "No such dock",
                        statusCode: 404,
                        extensions: new Dictionary<string, object?>
                        {
                            ["dockId"] = ex.DockId,
                        });
                }
                catch (DockFullException ex)
                {
                    return TypedResults.Problem(
                        title: "Dock full",
                        statusCode: 409,
                        extensions: new Dictionary<string, object?>
                        {
                            ["dockId"] = ex.DockId,
                            ["capacity"] = ex.Capacity,
                        });
                }
                // Anything else is a bug, and a bug with its stack trace intact
                // is worth more than a tidy 500.
            })
            .WithTags("v3da01");
    }

    private static IResult Park(string dockId, ParkRequest body)
    {
        var bike = V3DA01Review.Park(dockId, body.BikeId);

        return TypedResults.Created(
            $"/v3da01/review/docks/{dockId}/bikes/{bike.Id}",
            bike);
    }
}

lessons.fullReadme:
# V3·DA2 — Model binding, validation and problem details

## 1. The binding algorithm, written out

For every handler parameter, in this order:

| # | test | source |
|---|---|---|
| 1 | has a binding attribute | as stated |
| 2 | is a special type (`HttpContext`, `ClaimsPrincipal`, `CancellationToken`, `Stream`, `IFormFile`…) | the framework |
| 3 | name matches a route parameter | route |
| 4 | type has `TryParse` / is `string` | query |
| 5 | type has static `BindAsync` | whole request |
| 6 | type is registered in DI | services |
| 7 | otherwise | JSON body |

```csharp
app.MapPost("/v3da02/declarations/{id:int}/lines",
    (int id,                                        // 3: route
     [FromQuery] bool? draft,                       // 1
     [FromHeader(Name = "X-Declarant")] string who, // 1
     LineRequest body,                              // 7
     IDeclarationStore store,                       // 6
     CancellationToken ct) => ...);                 // 2
```

Rule 7 being a fallback is the one to fear. Forget to register
`IDeclarationStore` and the framework decides it must be the body — and since
there is already a body parameter, you get a startup exception about two body
parameters, which is a confusing way to be told about a missing registration.

## 2. Required, optional, empty

```csharp
(int quantity)     // missing -> 400 before your handler, empty body
(int? quantity)    // missing -> null, your problem
(string name)      // missing -> 400
(string? name)     // missing -> null
(LineRequest body) // empty body -> 400
([FromBody(EmptyBodyBehavior = EmptyBodyBehavior.Allow)] LineRequest? body) // -> null
```

Arrays from the query string:

```csharp
(int[] codes)          // ?codes=1&codes=2 -> [1,2]; absent -> []
(StringValues codes)   // absent -> StringValues.Empty (Count 0)
                       // ?codes= -> one entry, the empty string
```

## 3. Teaching the binder a type

### TryParse — one string in

```csharp
public readonly record struct TariffCode(string Value) : IParsable<TariffCode>
{
    public static TariffCode Parse(string s, IFormatProvider? provider) =>
        TryParse(s, provider, out var value)
            ? value
            : throw new FormatException("Tariff codes are four digits, a dot, two digits.");

    public static bool TryParse(string? s, IFormatProvider? provider, out TariffCode result)
    {
        result = default;
        if (s is null || s.Length != 7 || s[4] != '.') return false;
        if (!s.AsSpan(0, 4).ToString().All(char.IsAsciiDigit)) return false;
        if (!s.AsSpan(5, 2).ToString().All(char.IsAsciiDigit)) return false;
        result = new TariffCode(s);
        return true;
    }

    public override string ToString() => Value;
}
```

Now `(TariffCode code)` binds from the route or the query, and an invalid code
never reaches your handler.

### BindAsync — the whole request in

```csharp
public record DeclarantContext(string Declarant, string Office, int DeclarationId)
{
    public static ValueTask<DeclarantContext?> BindAsync(HttpContext http, ParameterInfo _)
    {
        var declarant = http.Request.Headers["X-Declarant"].ToString();
        var office = http.Request.Headers["X-Office"].ToString();

        if (string.IsNullOrWhiteSpace(declarant) || string.IsNullOrWhiteSpace(office))
            return ValueTask.FromResult<DeclarantContext?>(null);

        var id = int.Parse((string)http.Request.RouteValues["id"]!);
        return ValueTask.FromResult<DeclarantContext?>(new(declarant, office, id));
    }
}
```

`BindAsync` beats `TryParse` when both exist. Returning null is *not* an error;
throw `BadHttpRequestException` if you want a 400 from inside binding.

### AsParameters — many parameters, one type

```csharp
public readonly struct DeclarationQuery
{
    [FromQuery] public string? Office { get; init; }
    [FromQuery] public string? Status { get; init; }
    [FromQuery] public int? Page { get; init; }
    [FromQuery] public int? Size { get; init; }

    public Dictionary<string, string[]> Validate()
    {
        var errors = new Dictionary<string, string[]>();
        if (Page is < 1) errors["page"] = ["Must be 1 or more."];
        if (Size is < 1 or > 100) errors["size"] = ["Between 1 and 100."];
        return errors;
    }
}

app.MapGet("/v3da02/declarations", ([AsParameters] DeclarationQuery query) => ...);
```

## 4. Problem details

```csharp
builder.Services.AddProblemDetails(options =>
{
    options.CustomizeProblemDetails = context =>
    {
        context.ProblemDetails.Instance ??= context.HttpContext.Request.Path;
        context.ProblemDetails.Extensions["traceId"] =
            Activity.Current?.Id ?? context.HttpContext.TraceIdentifier;
    };
});
```

Producing one:

```csharp
TypedResults.Problem(title: "Declaration closed", statusCode: 409,
    extensions: new Dictionary<string, object?> { ["declarationId"] = id });

TypedResults.ValidationProblem(new Dictionary<string, string[]>
{
    ["quantity"] = ["Must be positive.", "Must be a whole number of units."],
    ["code"]     = ["Unknown tariff code."],
});
```

`ValidationProblem` gives 400 with `title` `"One or more validation errors
occurred."` and an `errors` member. To answer 422 instead, build the
`HttpValidationProblemDetails` yourself and pass `statusCode: 422`.

## 5. Exception handlers

```csharp
public class DeclarationClosedHandler : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext http, Exception exception, CancellationToken ct)
    {
        if (exception is not DeclarationClosedException closed) return false;

        http.Response.StatusCode = StatusCodes.Status409Conflict;
        return await http.RequestServices
            .GetRequiredService<IProblemDetailsService>()
            .TryWriteAsync(new ProblemDetailsContext
            {
                HttpContext = http,
                ProblemDetails =
                {
                    Title = "Declaration closed",
                    Status = StatusCodes.Status409Conflict,
                    Extensions = { ["declarationId"] = closed.DeclarationId },
                },
            });
    }
}
```

Register with `builder.Services.AddExceptionHandler<T>()` in order, most specific
first, and `app.UseExceptionHandler()` to run the chain.

## 6. Common mistakes

1. **Renaming a route segment and not the parameter.** Silent switch to query
   binding, silent null.
2. **A body parameter that is optional in your head only.** Absent body is a 400
   unless the type is nullable or `EmptyBodyBehavior.Allow` is set.
3. **Treating an empty array as "no filter".** `?codes=` gives you one empty
   string, and a filter of `codes.Contains(x)` then matches nothing.
4. **Custom `TryParse` that throws.** `TryParse` must return `false`, never
   throw; a throwing one surfaces as a 500 from inside binding.
5. **`AddProblemDetails` expected to fix bodies you wrote.** It only fills in
   empty ones.
6. **Validation attributes with no validator.** `[Required]` on a minimal API
   record does nothing on its own — minimal APIs have no automatic model
   validation. Either call the validator yourself, use a filter, or use a
   library.
7. **`catch (Exception)` in a handler that returns 400.** You have converted a
   bug into a client error and lost the stack trace.

## 7. The interview answer

> *"How does an ASP.NET Core minimal API decide where a parameter comes from, and
> what happens when the value is wrong?"*

Binding source is chosen at build time by a fixed rule order: explicit attribute,
special type, route-name match, simple type from the query, `BindAsync`, DI, then
the JSON body as a fallback. Failures split three ways, and they are worth
separating: an unparseable simple value or a malformed body is a framework 400
raised before the handler; a wrong `Content-Type` is a 415; and a value that
parsed but is invalid is a business concern the handler owns. The framework's
default 400 has an empty body, so a serious API adds `AddProblemDetails` and
returns RFC 9457 documents with an `errors` dictionary keyed by the client's
field names, plus a `traceId` extension so a support conversation can be joined
to a log entry.

## 8. Check yourself

1. List the binding-source rules in order. Which one is the fallback, and why is
   that dangerous?
2. A route is `/{declarationId}` and the handler parameter is `int id`. What
   happens?
3. What is the difference between `int q` and `int? q` when `?q=` is absent?
4. What does `?codes=` (present, empty) bind to for a parameter of type
   `string[]`?
5. Which wins when a type has both `TryParse` and `BindAsync`?
6. What does returning `null` from `BindAsync` mean, and how do you fail instead?
7. Is a JSON body parameter required by default? How do you make it optional?
8. What status does a `Content-Type: text/plain` body produce, and who produces
   it?
9. What exactly does `AddProblemDetails` change, and what does it not change?
10. Name three members of a problem document defined by RFC 9457 and two common
    extensions.
11. When would you return 422 rather than 400, and what is the argument against?
12. What does returning `false` from `IExceptionHandler.TryHandleAsync` do?
13. Why do minimal APIs not run `[Required]` and `[Range]` attributes for you?

