using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Primitives;

namespace DotnetDojo.Api.V3DA02_BindingValidation;

public class Ex2 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var lines = app.MapGroup("/v3da02/lines").WithTags("v3da02");

        lines.MapGet("/filter", Filter);
        lines.MapGet("/matching", Matching);
    }

    private static IResult Filter(
        [FromQuery(Name = "code")] string[] codesArray,
        [FromQuery(Name = "code")] StringValues codesValues,
        [FromQuery(Name = "office")] string? office) =>
        TypedResults.Ok(new
        {
            arrayCount = codesArray.Length,
            valuesCount = codesValues.Count,
            first = codesArray.Length > 0 ? codesArray[0] : null,
            officeIsNull = office is null,
            officeIsEmpty = office == string.Empty,
        });

    private static IResult Matching([FromQuery(Name = "code")] string[] codes)
    {
        // Drop the empty entries first: "?code=" is a present key with no value,
        // and treating it as a filter matches nothing at all.
        var wanted = codes.Where(c => !string.IsNullOrEmpty(c)).ToHashSet(StringComparer.Ordinal);

        var lines = V3DA02Store.Declarations
            .SelectMany(d => d.Lines)
            .Where(l => wanted.Count == 0 || wanted.Contains(l.Code))
            .OrderBy(l => l.Id)
            .ToList();

        return TypedResults.Ok(lines);
    }
}

