// v3da02_binding_validation_problems / ex3 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA02_BindingValidation;

public readonly record struct TariffCode(string Value) : IParsable<TariffCode>
{
    public static TariffCode Parse(string s, IFormatProvider? provider) =>
        TryParse(s, provider, out var value)
            ? value
            : throw new FormatException("Tariff codes are four digits, a dot, two digits.");

    // Must never throw: a throwing TryParse becomes a 500 from inside binding.
    public static bool TryParse(string? s, IFormatProvider? provider, out TariffCode result)
    {
        result = default;

        if (s is not { Length: 7 } || s[4] != '.')
        {
            return false;
        }

        for (var i = 0; i < 7; i++)
        {
            if (i == 4)
            {
                continue;
            }

            if (!char.IsAsciiDigit(s[i]))
            {
                return false;
            }
        }

        result = new TariffCode(s);

        return true;
    }

    public override string ToString() => Value;
}

public class Ex3 : IEndpointMapper
{
    private const string Message = "Tariff codes are four digits, a dot, two digits.";

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var tariffs = app.MapGroup("/v3da02/tariffs").WithTags("v3da02");

        tariffs.MapGet("/lenient", Lenient);
        tariffs.MapGet("/{code}", Strict);
    }

    // Strongly bound: an invalid code never reaches this method, at the cost of
    // a framework 400 with nothing in it.
    private static IResult Strict(TariffCode code) =>
        TypedResults.Ok(new { code = code.Value, known = Known(code.Value) });

    // Loosely bound: three extra lines buy a message with the field name in it.
    private static IResult Lenient(string? code)
    {
        if (!TariffCode.TryParse(code, null, out var parsed))
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["code"] = [Message],
            });
        }

        return TypedResults.Ok(new { code = parsed.Value, known = Known(parsed.Value) });
    }

    private static bool Known(string code) =>
        V3DA02Store.Declarations.SelectMany(d => d.Lines).Any(l => l.Code == code);
}

