using System.Reflection;

namespace DotnetDojo.Api.V3DA02_BindingValidation;

public record DeclarantContext(string Declarant, string Office, int DeclarationId)
{
    public static ValueTask<DeclarantContext?> BindAsync(HttpContext http, ParameterInfo parameter)
    {
        var declarant = http.Request.Headers["X-Declarant"].ToString();
        var office = http.Request.Headers["X-Office"].ToString();

        // null is "absent", not "invalid" - the parameter's nullability decides
        // whether absent is acceptable.
        if (string.IsNullOrWhiteSpace(declarant) || string.IsNullOrWhiteSpace(office))
        {
            return ValueTask.FromResult<DeclarantContext?>(null);
        }

        if (office.Length != 3 || !office.All(char.IsAsciiLetterUpper))
        {
            throw new BadHttpRequestException("X-Office must be three capitals.", 400);
        }

        var declarationId = int.Parse((string)http.Request.RouteValues["declarationId"]!);

        return ValueTask.FromResult<DeclarantContext?>(
            new DeclarantContext(declarant, office, declarationId));
    }
}

public class Ex4 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da02/declarations/{declarationId:int}/context", GetContext)
            .WithTags("v3da02");

        app.MapGet("/v3da02/declarations/{declarationId:int}/strict-context", GetStrict)
            .WithTags("v3da02");
    }

    private static IResult GetContext(DeclarantContext? context) =>
        context is null
            ? TypedResults.Problem(title: "Declarant headers required", statusCode: 401)
            : TypedResults.Ok(Shape(context));

    // Non-nullable: a null from BindAsync is a binding failure, so the framework
    // answers 400 and this method is never entered.
    private static IResult GetStrict(DeclarantContext context) => TypedResults.Ok(Shape(context));

    private static object Shape(DeclarantContext context) => new
    {
        declarant = context.Declarant,
        office = context.Office,
        declarationId = context.DeclarationId,
    };
}

