// v3da02_binding_validation_problems / ex5 - reference solution (author only, used by `dojo verify`).

using Microsoft.AspNetCore.Mvc;

namespace DotnetDojo.Api.V3DA02_BindingValidation;

public readonly struct DeclarationQuery
{
    [FromQuery] public string? Office { get; init; }

    [FromQuery] public string? Status { get; init; }

    [FromQuery(Name = "code")] public string[] Codes { get; init; }

    [FromQuery] public int? MinQuantity { get; init; }

    [FromQuery] public int? Page { get; init; }

    [FromQuery] public int? Size { get; init; }

    [FromQuery] public string? Sort { get; init; }

    public Dictionary<string, string[]> Validate()
    {
        var errors = new Dictionary<string, string[]>();

        // Every rule is checked: a client fixing three mistakes one round trip
        // at a time is a client that stops integrating.
        if (Page is < 1)
        {
            errors["page"] = ["Must be 1 or more."];
        }

        if (Size is < 1 or > 100)
        {
            errors["size"] = ["Between 1 and 100."];
        }

        if (MinQuantity is < 0)
        {
            errors["minQuantity"] = ["Must not be negative."];
        }

        if (Status is not null && Status != "open" && Status != "closed")
        {
            errors["status"] = ["Must be open or closed."];
        }

        if (Sort is not null && Sort != "id" && Sort != "office" && Sort != "status")
        {
            errors["sort"] = ["Must be id, office or status."];
        }

        if (Office is not null && (Office.Length != 3 || !Office.All(char.IsAsciiLetterUpper)))
        {
            errors["office"] = ["Must be three capitals."];
        }

        return errors;
    }
}

public class Ex5 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da02/search", Search).WithTags("v3da02");
    }

    private static IResult Search([AsParameters] DeclarationQuery query)
    {
        var errors = query.Validate();
        if (errors.Count > 0)
        {
            return TypedResults.ValidationProblem(errors);
        }

        var codes = (query.Codes ?? [])
            .Where(c => !string.IsNullOrEmpty(c))
            .ToHashSet(StringComparer.Ordinal);

        IEnumerable<Declaration> found = V3DA02Store.Declarations;

        if (query.Office is not null)
        {
            found = found.Where(d => d.Office == query.Office);
        }

        if (query.Status is not null)
        {
            found = found.Where(d => d.Status == query.Status);
        }

        if (codes.Count > 0)
        {
            found = found.Where(d => d.Lines.Any(l => codes.Contains(l.Code)));
        }

        if (query.MinQuantity is { } min)
        {
            found = found.Where(d => d.Lines.Any(l => l.Quantity >= min));
        }

        found = (query.Sort ?? "id") switch
        {
            "office" => found.OrderBy(d => d.Office, StringComparer.Ordinal),
            "status" => found.OrderBy(d => d.Status, StringComparer.Ordinal),
            _ => found.OrderBy(d => d.Id),
        };

        var matched = found.ToList();
        var page = query.Page ?? 1;
        var size = query.Size ?? 20;

        var items = matched
            .Skip((page - 1) * size)
            .Take(size)
            .Select(d => new { id = d.Id, office = d.Office, status = d.Status })
            .ToList();

        // total is the pre-pagination count: it is what a pager renders from.
        return TypedResults.Ok(new { page, size, total = matched.Count, items });
    }
}

