namespace DotnetDojo.Api.V3DA02_BindingValidation;

public record SubmitRequest(string Office, List<LineRequest> Lines, string? Reference);

public class Ex7 : IEndpointMapper
{
    private static readonly string[] Offices = ["LHR", "DOV"];

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3da02/declarations/{declarationId:int}/submit", Submit)
            .WithTags("v3da02");
    }

    private static IResult Submit(int declarationId, SubmitRequest body)
    {
        var declaration = V3DA02Store.Find(declarationId);

        // Existence, then state, then content. A closed declaration with a
        // flawless body is still a 409.
        if (declaration is null)
        {
            return TypedResults.NotFound();
        }

        if (declaration.Status == "closed")
        {
            return TypedResults.Problem(
                title: "Declaration closed",
                statusCode: 409,
                extensions: new Dictionary<string, object?> { ["declarationId"] = declarationId });
        }

        var errors = Validate(body);
        if (errors.Count > 0)
        {
            return TypedResults.ValidationProblem(
                errors,
                statusCode: 422,
                title: "The declaration was rejected.",
                extensions: new Dictionary<string, object?> { ["declarationId"] = declarationId });
        }

        return TypedResults.Ok(new { declarationId, lines = body.Lines.Count });
    }

    private static Dictionary<string, string[]> Validate(SubmitRequest body)
    {
        var errors = new Dictionary<string, string[]>();

        // One key, possibly several messages - collected then assigned once.
        var office = new List<string>();
        if (body.Office is null || body.Office.Length != 3 || !body.Office.All(char.IsAsciiLetterUpper))
        {
            office.Add("Must be three capitals.");
        }

        if (body.Office is null || !Offices.Contains(body.Office))
        {
            office.Add("Must be a known office.");
        }

        if (office.Count > 0)
        {
            errors["office"] = [.. office];
        }

        if (body.Lines is null || body.Lines.Count == 0)
        {
            errors["lines"] = ["At least one line is required."];
        }
        else
        {
            for (var i = 0; i < body.Lines.Count; i++)
            {
                var line = body.Lines[i];

                if (!TariffCode.TryParse(line.Code, null, out _))
                {
                    errors[$"lines[{i}].code"] =
                        ["Tariff codes are four digits, a dot, two digits."];
                }

                if (line.Quantity < 1)
                {
                    errors[$"lines[{i}].quantity"] = ["Must be positive."];
                }
            }
        }

        if (body.Reference is { Length: > 16 })
        {
            errors["reference"] = ["Must be at most 16 characters."];
        }

        return errors;
    }
}

