        {
            return false;
        }

        http.Response.StatusCode = StatusCodes.Status409Conflict;

        return await problems.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = http,
            ProblemDetails =
            {
                Title = "Declaration closed",
                Status = StatusCodes.Status409Conflict,
                Extensions = { ["declarationId"] = closed.DeclarationId },
            },
        });
    }
}

public class TariffHandler(IProblemDetailsService problems) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext http, Exception exception, CancellationToken cancellationToken)
    {
        if (exception is not TariffUnknownException unknown)
        {
            return false;
        }

        http.Response.StatusCode = StatusCodes.Status422UnprocessableEntity;

        return await problems.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = http,
            ProblemDetails =
            {
                Title = "Unknown tariff code",
                Status = StatusCodes.Status422UnprocessableEntity,
                Extensions = { ["code"] = unknown.Code },
            },
        });
    }
}

public class LastResortHandler(
    IProblemDetailsService problems,
    ILogger<LastResortHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext http, Exception exception, CancellationToken cancellationToken)
    {
        // The only handler allowed to claim everything, and the only one that
        // should log: the two above describe expected outcomes, this one is an
        // incident.
        logger.LogError(exception, "Unhandled failure on {Path}", http.Request.Path);

        http.Response.StatusCode = StatusCodes.Status500InternalServerError;

        return await problems.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = http,
            ProblemDetails =
            {
                Title = "Unexpected failure",
                Status = StatusCodes.Status500InternalServerError,
                Extensions = { ["handled"] = "last-resort" },
            },
        });
    }
}

public class Ex8Services : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        // Order is the contract: the catch-all goes last or it eats the others.
        services.AddExceptionHandler<ClosedHandler>();
        services.AddExceptionHandler<TariffHandler>();
        services.AddExceptionHandler<LastResortHandler>();
    }
}

