using System.Diagnostics;
using Microsoft.AspNetCore.Mvc;

namespace DotnetDojo.Api.V3DA02_BindingValidation;

public record ReplaceRequest(int Quantity, string? Note);

public readonly struct ReplaceOptions
{
    [FromQuery] public bool? Force { get; init; }

    [FromQuery] public int? Version { get; init; }
}

public class ChallengeServices : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddProblemDetails(options =>
        {
            options.CustomizeProblemDetails = context =>
            {
                context.ProblemDetails.Instance ??= context.HttpContext.Request.Path;
                context.ProblemDetails.Extensions["traceId"] =
                    Activity.Current?.Id ?? context.HttpContext.TraceIdentifier;
                context.ProblemDetails.Extensions["service"] = "v3da02";
            };
        });
    }
}

public class Challenge : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPut("/v3da02/declarations/{declarationId:int}/lines/{code}", Replace)
            .WithTags("v3da02");
    }

    private static IResult Replace(
        int declarationId,
        TariffCode code,
        DeclarantContext? declarant,
        [AsParameters] ReplaceOptions options,
        ReplaceRequest body)
    {
        // 1 - who are you
        if (declarant is null)
        {
            return TypedResults.Problem(title: "Declarant headers required", statusCode: 401);
        }

        // 2 - does it exist
        var declaration = V3DA02Versions.Find(declarationId);
        if (declaration is null)
        {
            return TypedResults.Problem(title: "No such declaration", statusCode: 404);
        }

        // 3 - is it writable
        if (declaration.Status == "closed" && options.Force is not true)
        {
            return TypedResults.Problem(
                title: "Declaration closed",
                statusCode: 409,
                extensions: new Dictionary<string, object?> { ["declarationId"] = declarationId });
        }

        // 4 - are we looking at the same version; force does not relax this one
        if (options.Version is { } expected && expected != declaration.Version)
        {
            return TypedResults.Problem(
                title: "Version mismatch",
                statusCode: 412,
                extensions: new Dictionary<string, object?>
                {
                    ["expected"] = expected,
                    ["actual"] = declaration.Version,
                });
        }

        // 5 - is the content acceptable
        var errors = new Dictionary<string, string[]>();

        if (body.Quantity < 1)
        {
            errors["quantity"] = ["Must be positive."];
        }

        if (body.Note is { Length: > 40 })
        {
            errors["note"] = ["Must be at most 40 characters."];
        }

        if (errors.Count > 0)
        {
            return TypedResults.ValidationProblem(
                errors,
                statusCode: 422,
                title: "The line was rejected.");
        }

        // 6 - do the work
        var version = V3DA02Versions.Replace(declaration, code.Value, body.Quantity);

        return TypedResults.Ok(new
        {
            declarationId,
            code = code.Value,
            quantity = body.Quantity,
            version,
        });
    }
}

