// v3da02_binding_validation_problems / review1 - reference solution (author only, used by `dojo verify`).

using Microsoft.AspNetCore.Mvc;

namespace DotnetDojo.Api.V3DA02_BindingValidation;

public class Review1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var review = app.MapGroup("/v3da02/review/declarations").WithTags("v3da02");

        review.MapGet("/", List);
        review.MapGet("/{declarationId:int}", Get);
    }

    private static IResult Get(int declarationId, HttpContext http)
    {
        var accept = http.Request.Headers.Accept.ToString();

        // Minimal APIs do not negotiate content: a 406 is a decision, not a
        // default, and it applies before anything about the resource.
        if (!string.IsNullOrEmpty(accept)
            && !accept.Contains("application/json", StringComparison.OrdinalIgnoreCase)
            && !accept.Contains("*/*", StringComparison.Ordinal))
        {
            return TypedResults.Problem(
                title: "Only application/json is available",
                statusCode: 406,
                extensions: new Dictionary<string, object?> { ["accept"] = accept });
        }

        var declaration = V3DA02Versions.Find(declarationId);
        if (declaration is null)
        {
            return TypedResults.Problem(title: "No such declaration", statusCode: 404);
        }

        var etag = $"\"v{declaration.Version}\"";
        http.Response.Headers.ETag = etag;

        if (http.Request.Headers.IfNoneMatch.Any(v => v == etag))
        {
            // No body, and the validator it matched is already on the response.
            return TypedResults.StatusCode(StatusCodes.Status304NotModified);
        }

        http.Response.Headers.CacheControl = "no-cache";

        return TypedResults.Ok(new
        {
            id = declaration.Id,
            office = declaration.Office,
            status = declaration.Status,
            version = declaration.Version,
        });
    }

    private static IResult List([FromHeader(Name = "X-Page-Size")] int? pageSize)
    {
        if (pageSize is < 1 or > 50)
        {
            // The key names the input the client controls: a header, not a
            // parameter of a C# method they cannot see.
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["X-Page-Size"] = ["Between 1 and 50."],
            });
        }

        var items = V3DA02Versions.All()
            .OrderBy(d => d.Id)
            .Take(pageSize ?? 20)
            .Select(d => new { id = d.Id, office = d.Office, status = d.Status })
            .ToList();

        return TypedResults.Ok(items);
    }
}

