using System.Security.Claims;
using Microsoft.IdentityModel.Tokens;

namespace DotnetDojo.Api.V3DA03_AuthSchemes;

public class Ex3Services : IServiceRegistrar
{
    public const string Strict = "v3da03-ex3-strict";
    public const string NoAudience = "v3da03-ex3-noaud";
    public const string Skew = "v3da03-ex3-skew";
    public const string NoLifetime = "v3da03-ex3-nolife";

    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        var auth = services.AddAuthentication();

        auth.AddJwtBearer(Strict, o => o.TokenValidationParameters = Baseline());

        auth.AddJwtBearer(NoAudience, o =>
        {
            var p = Baseline();
            p.ValidateAudience = false;
            o.TokenValidationParameters = p;
        });

        auth.AddJwtBearer(Skew, o =>
        {
            var p = Baseline();
            p.ClockSkew = new TokenValidationParameters().ClockSkew; // the default: 5 minutes
            o.TokenValidationParameters = p;
        });

        auth.AddJwtBearer(NoLifetime, o =>
        {
            var p = Baseline();
            p.ValidateLifetime = false;
            o.TokenValidationParameters = p;
        });
    }

    // A factory, not a shared field: the handler mutates the parameters it is
    // given, and four schemes sharing one instance is a very confusing bug.
    private static TokenValidationParameters Baseline() => new()
    {
        ValidateIssuer = true,
        ValidIssuer = V3DA03Jwt.Issuer,
        ValidateAudience = true,
        ValidAudience = V3DA03Jwt.Audience,
        ValidateLifetime = true,
        ClockSkew = TimeSpan.Zero,
        ValidateIssuerSigningKey = true,
        IssuerSigningKey = V3DA03Jwt.SigningKey,
        NameClaimType = "sub",
        RoleClaimType = "role",
    };
}

public class Ex3 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        Map(app, "strict", Ex3Services.Strict);
        Map(app, "noaud", Ex3Services.NoAudience);
        Map(app, "skew", Ex3Services.Skew);
        Map(app, "nolife", Ex3Services.NoLifetime);
    }

    private static void Map(IEndpointRouteBuilder app, string name, string scheme)
