                TypedResults.Ok(new { scheme = name, sub = user.FindFirst("sub")?.Value }))
            .RequireAuthorization(policy => policy
                .AddAuthenticationSchemes(scheme)
                .RequireAuthenticatedUser())
            .WithTags("v3da03");
    }
