using System.Security.Claims;
using System.Text.Encodings.Web;
using Microsoft.AspNetCore.Authentication;
using Microsoft.Extensions.Options;

namespace DotnetDojo.Api.V3DA03_AuthSchemes;

public class ApiKeyOptions : AuthenticationSchemeOptions
{
    public string HeaderName { get; set; } = "X-Wire-Key";

    public Dictionary<string, string> Keys { get; set; } = new();
}

public class ApiKeyHandler(
    IOptionsMonitor<ApiKeyOptions> options,
    ILoggerFactory logger,
    UrlEncoder encoder)
    : AuthenticationHandler<ApiKeyOptions>(options, logger, encoder)
{
    protected override Task<AuthenticateResult> HandleAuthenticateAsync()
    {
        if (!Request.Headers.TryGetValue(Options.HeaderName, out var supplied)
            || string.IsNullOrEmpty(supplied))
        {
            // Not my request - another scheme may still succeed.
            return Task.FromResult(AuthenticateResult.NoResult());
        }

        if (!Options.Keys.TryGetValue(supplied.ToString(), out var subject))
        {
            // My request, and it is wrong.
            return Task.FromResult(AuthenticateResult.Fail("Unknown API key."));
        }

        // A non-null authentication type is what makes the identity authenticated.
        var identity = new ClaimsIdentity(
            [new Claim("sub", subject), new Claim("role", "service")],
            Scheme.Name,
            "sub",
            "role");

        var ticket = new AuthenticationTicket(new ClaimsPrincipal(identity), Scheme.Name);

        return Task.FromResult(AuthenticateResult.Success(ticket));
    }

    protected override Task HandleChallengeAsync(AuthenticationProperties properties)
    {
        Response.StatusCode = StatusCodes.Status401Unauthorized;
        Response.Headers.WWWAuthenticate = "ApiKey realm=\"wire\"";

        return Task.CompletedTask;
    }
}

public class Ex5Services : IServiceRegistrar
{
    public const string Scheme = "v3da03-ex5-key";

    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddAuthentication()
            .AddScheme<ApiKeyOptions, ApiKeyHandler>(Scheme, options =>
            {
                options.HeaderName = "X-Wire-Key";
                options.Keys = new Dictionary<string, string>
                {
                    ["wire-abc"] = "feed-service",
                    ["wire-def"] = "archive-service",
                };
            });
    }
}

public class Ex5 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da03/keyed/feed", (ClaimsPrincipal user) => TypedResults.Ok(new
            {
                sub = user.FindFirst("sub")?.Value,
                role = user.FindFirst("role")?.Value,
                scheme = user.Identity!.AuthenticationType,
            }))
            .RequireAuthorization(policy => policy
                .AddAuthenticationSchemes(Ex5Services.Scheme)
                .RequireAuthenticatedUser())
            .WithTags("v3da03");
    }
}

