using System.Security.Claims;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;

namespace DotnetDojo.Api.V3DA03_AuthSchemes;

public class Ex6Services : IServiceRegistrar
{
    public const string Jwt = "v3da03-ex6-jwt";
    public const string Key = "v3da03-ex6-key";
    public const string Either = "v3da03-ex6-either";

    public static int JwtAttempts;

    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        var auth = services.AddAuthentication();

        auth.AddPolicyScheme(Either, "Bearer or API key", options =>
        {
            // Cheap, header-only, no I/O: this runs on every request.
            options.ForwardDefaultSelector = http =>
                http.Request.Headers.ContainsKey("X-Wire-Key") ? Key : Jwt;
        });

        auth.AddJwtBearer(Jwt, options =>
        {
            options.MapInboundClaims = false;
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidIssuer = V3DA03Jwt.Issuer,
                ValidateAudience = true,
                ValidAudience = V3DA03Jwt.Audience,
                ValidateLifetime = true,
                ClockSkew = TimeSpan.Zero,
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = V3DA03Jwt.SigningKey,
                NameClaimType = "sub",
                RoleClaimType = "role",
            };

            options.Events = new JwtBearerEvents
            {
                OnMessageReceived = context =>
                {
                    Interlocked.Increment(ref JwtAttempts);

                    return Task.CompletedTask;
                },
            };
        });

        auth.AddScheme<ApiKeyOptions, ApiKeyHandler>(Key, options =>
        {
            options.HeaderName = "X-Wire-Key";
            options.Keys = new Dictionary<string, string> { ["wire-xyz"] = "syndication" };
        });
    }
}

public class Ex6 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var either = app.MapGroup("/v3da03/either").WithTags("v3da03");

        // Both handlers run; identities are merged.
        either.MapGet("/listed", Describe)
            .RequireAuthorization(policy => policy
                .AddAuthenticationSchemes(Ex6Services.Jwt, Ex6Services.Key)
                .RequireAuthenticatedUser());

        // One handler runs, chosen per request.
        either.MapGet("/forwarded", Describe)
            .RequireAuthorization(policy => policy
                .AddAuthenticationSchemes(Ex6Services.Either)
                .RequireAuthenticatedUser());

        either.MapGet("/count", () =>
            TypedResults.Ok(new { jwtAttempts = Ex6Services.JwtAttempts }));
    }

    private static IResult Describe(ClaimsPrincipal user) =>
        TypedResults.Ok(new
        {
            sub = user.FindFirst("sub")?.Value,
            via = user.Identity!.AuthenticationType,
        });
}

exercises.hints:
## Hint 1

Two events, two jobs. `OnAuthenticationFailed` is the only place the exception
exists; `OnChallenge` is the only place the response is written. Neither can do
the other's work, which is why you need somewhere to put the reason in between.

## Hint 2

Taking over a challenge:

    OnChallenge = context =>
    {
        context.HandleResponse();     // stop the default 401 being written
        context.Response.StatusCode = StatusCodes.Status401Unauthorized;
        context.Response.Headers.WWWAuthenticate = "Bearer realm=\"wire\"";
        return context.Response.WriteAsJsonAsync(new { title = "Token rejected" });
    };

Without `HandleResponse()` the handler writes its own 401 after yours and you get
a headers-already-sent exception.

## Hint 3

`HttpContext.Items` is the per-request carrier between the two events. The
decision left to you: `Items` or `AuthenticateResult.Failure` read back in
`OnChallenge` via `context.AuthenticateFailure`? The second is more direct and
needs you to map the exception twice — pick, and know why the other exists.

