                        // The only place the exception is available.
                        context.HttpContext.Items[ReasonKey] = context.Exception switch
                        {
                            SecurityTokenExpiredException => "expired",
                            SecurityTokenInvalidAudienceException => "audience",

                            // Collapsed on purpose: a caller who cannot sign the
                            // token can do nothing with this, and a prober learns
                            // exactly how far they got.
                            SecurityTokenInvalidSignatureException => "invalid",
                            _ => "invalid",
                        };

                        return Task.CompletedTask;
                    },

                    OnChallenge = context =>
                    {
                        context.HandleResponse();

                        var reason = context.HttpContext.Items[ReasonKey] as string ?? "absent";

                        context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                        context.Response.Headers.WWWAuthenticate = reason == "absent"
                            ? "Bearer"
                            : $"Bearer error=\"invalid_token\", error_description=\"{reason}\"";
                        context.Response.ContentType = "application/problem+json";

                        return context.Response.WriteAsJsonAsync(new
                        {
                            title = "Token rejected",
                            status = 401,
                            reason,
                        });
                    },
                };
            });
    }
}

