public class Ex8 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var open = app.MapGroup("/v3da03/public").WithTags("v3da03");

        // No RequireAuthorization anywhere: nothing here rejects a caller.
        open.MapGet("/stories", ListStories);
        open.MapPost("/token", IssueToken);
    }

    private static async Task<IResult> ListStories(HttpContext http)
    {
        var result = await http.AuthenticateAsync(Ex8Services.Scheme);

        // A bad token fails here and writes nothing: the caller is simply
        // anonymous, because we never challenged.
        var viewer = result.Succeeded ? result.Principal!.FindFirst("sub")?.Value : null;
        var embargoed = result.Succeeded && result.Principal!.IsInRole("editor");

        var stories = V3DA03Wire.Stories
            .Where(s => embargoed || !s.Embargoed)
            .OrderBy(s => s.Id)
            .Select(s => s.Headline)
            .ToList();

        return TypedResults.Ok(new { viewer, embargoed, stories });
    }

    private static IResult IssueToken(TokenRequest body)
    {
        var claims = body.Role is null
            ? new[] { new System.Security.Claims.Claim("sub", body.Sub) }
            : [new System.Security.Claims.Claim("sub", body.Sub),
               new System.Security.Claims.Claim("role", body.Role)];

        return TypedResults.Ok(new { token = V3DA03Jwt.Mint(Ex8Services.Scheme, claims) });
    }
}

