using System.Security.Claims;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;

namespace DotnetDojo.Api.V3DA03_AuthSchemes;

public class ChallengeServices : IServiceRegistrar
{
    public const string Jwt = "v3da03-ch-jwt";
    public const string Key = "v3da03-ch-key";
    public const string Either = "v3da03-ch";

    private const string ReasonKey = "v3da03-ch-reason";

    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        var auth = services.AddAuthentication();

        auth.AddPolicyScheme(Either, "Bearer or API key", options =>
        {
            // Presence, not validity: validating here would move authentication
            // into selection, and a bad key would fall through to bearer.
            options.ForwardDefaultSelector = http =>
                http.Request.Headers.ContainsKey("X-Wire-Key") ? Key : Jwt;
        });

        auth.AddJwtBearer(Jwt, options =>
        {
            options.MapInboundClaims = false;
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidIssuer = V3DA03Jwt.Issuer,
                ValidateAudience = true,
                ValidAudience = V3DA03Jwt.Audience,
                ValidateLifetime = true,
                ClockSkew = TimeSpan.Zero,
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = V3DA03Jwt.SigningKey,
                NameClaimType = "sub",
                RoleClaimType = "role",
            };

            options.Events = new JwtBearerEvents
            {
                OnAuthenticationFailed = context =>
                {
                    context.HttpContext.Items[ReasonKey] = context.Exception switch
                    {
                        SecurityTokenExpiredException => "expired",
                        SecurityTokenInvalidAudienceException => "audience",
                        _ => "invalid",
                    };

                    return Task.CompletedTask;
                },
                OnChallenge = context =>
                {
                    context.HandleResponse();

                    var reason = context.HttpContext.Items[ReasonKey] as string;

                    context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                    context.Response.Headers.WWWAuthenticate = reason is null
                        ? "Bearer"
                        : $"Bearer error=\"invalid_token\", error_description=\"{reason}\"";

                    return Task.CompletedTask;
                },
            };
        });

        auth.AddScheme<ApiKeyOptions, ApiKeyHandler>(Key, options =>
        {
            options.HeaderName = "X-Wire-Key";
            options.Keys = new Dictionary<string, string>
            {
                ["syn-1"] = "syndication",
                ["syn-2"] = "archive",
            };
        });

        // One vocabulary for both credentials: the key handler adds `desk` so
        // that no endpoint has to know which scheme authenticated the caller.
        services.PostConfigure<ApiKeyOptions>(Key, _ => { });
    }
}

public class Challenge : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var mixed = app.MapGroup("/v3da03/mixed")
            .WithTags("v3da03")
            .RequireAuthorization(policy => policy
                .AddAuthenticationSchemes(ChallengeServices.Either)
                .RequireAuthenticatedUser());

        mixed.MapGet("/stories", ListStories);

        mixed.MapGet("/desk", GetDesk)
            .RequireAuthorization(policy => policy
                .AddAuthenticationSchemes(ChallengeServices.Either)
                .RequireAuthenticatedUser()
                .RequireClaim("desk"));

        mixed.MapPost("/spike/{id:int}", Spike)
            .RequireAuthorization(policy => policy
                .AddAuthenticationSchemes(ChallengeServices.Either)
                .RequireAuthenticatedUser()
                .RequireRole("editor"));
    }

    private static IResult ListStories(ClaimsPrincipal user)
    {
        var embargoed = user.IsInRole("editor");

        return TypedResults.Ok(new
        {
            stories = V3DA03Wire.Stories
                .Where(s => embargoed || !s.Embargoed)
                .OrderBy(s => s.Id)
                .Select(s => s.Headline)
                .ToList(),
        });
    }

    private static IResult GetDesk(ClaimsPrincipal user) => TypedResults.Ok(new
    {
        desk = user.FindFirst("desk")?.Value,
        via = user.Identity!.AuthenticationType,
    });

    private static IResult Spike(int id)
    {
        var story = V3DA03Wire.Stories.FirstOrDefault(s => s.Id == id);
        if (story is null)
        {
            return TypedResults.NotFound();
        }

        if (story.Spiked)
        {
            return TypedResults.Problem(title: "Already spiked", statusCode: 409);
        }

        story.Spiked = true;

        return TypedResults.NoContent();
    }
}

