using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;

namespace DotnetDojo.Api.V3DA04_AuthorizationPolicies;

public record ScoreChange(int Score);

public class ReviewerAssignmentHandler
    : AuthorizationHandler<ProposalAccessRequirement, Proposal>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        ProposalAccessRequirement requirement,
        Proposal resource)
    {
        var sub = context.User.FindFirst("sub")?.Value;

        if ((sub is not null && resource.Reviewers.Contains(sub))
            || context.User.IsInRole("chair"))
        {
            context.Succeed(requirement);
        }

        return Task.CompletedTask;
    }
}

public class Ex5Services : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<IAuthorizationHandler, ReviewerAssignmentHandler>();

        services.AddAuthorizationBuilder()
            .AddPolicy(V3DA04Policies.Reviewer, policy => policy
                .AddAuthenticationSchemes(V3DA04Jwt.Scheme)
                .RequireAuthenticatedUser())
            // Never used with RequireAuthorization: the middleware would pass
            // the HttpContext as the resource and the typed handler would be
            // filtered out by its own base class.
            .AddPolicy(V3DA04Policies.ScoreProposal, policy => policy
                .AddRequirements(new ProposalAccessRequirement()));
    }
}

public class Ex5 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPut("/v3da04/proposals/{id:int}/score", SetScore)
            .RequireAuthorization(V3DA04Policies.Reviewer)
            .WithTags("v3da04");
    }

    private static async Task<IResult> SetScore(
        int id,
        ScoreChange body,
        ClaimsPrincipal user,
        IAuthorizationService authorization)
    {
        var proposal = V3DA04Board.Find(id);
        if (proposal is null)
        {
            return TypedResults.NotFound();
        }

        // The resource exists now, so the question that needed it can be asked -
        // and it is asked before the payload is looked at.
        var decision = await authorization.AuthorizeAsync(
            user, proposal, V3DA04Policies.ScoreProposal);

        if (!decision.Succeeded)
        {
            return TypedResults.Forbid(authenticationSchemes: [V3DA04Jwt.Scheme]);
        }

        if (body.Score is < 0 or > 10)
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["score"] = ["A score is 0 to 10."],
            });
        }

        proposal.Score = body.Score;

        return TypedResults.NoContent();
    }
}

