using Microsoft.AspNetCore.Authorization;

namespace DotnetDojo.Api.V3DA04_AuthorizationPolicies;

// A veto handler. It never succeeds; refusing is its whole job.
public class ConflictOfInterestHandler
    : AuthorizationHandler<ReviewRemovalRequirement, Proposal>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        ReviewRemovalRequirement requirement,
        Proposal resource)
    {
        Interlocked.Increment(ref Ex6.HandlerRuns);

        var sub = context.User.FindFirst("sub")?.Value;

        if (sub is not null && resource.Conflicts.Contains(sub))
        {
            // Beats any sibling success, including the chair's.
            context.Fail(new AuthorizationFailureReason(
                this, "A conflict of interest is declared."));
        }

        return Task.CompletedTask;
    }
}

public class Ex6Services : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<IAuthorizationHandler, ReviewRemovalHandler>();
        services.AddSingleton<IAuthorizationHandler, ConflictOfInterestHandler>();

        services.Configure<AuthorizationOptions>(options =>
        {
            // Cheaper, and the reason a caller sees now depends on registration
            // order - a trade worth making on purpose.
            options.InvokeHandlersAfterFailure = false;
        });

        services.AddAuthorizationBuilder()
            .AddPolicy(V3DA04Policies.Reviewer, policy => policy
                .AddAuthenticationSchemes(V3DA04Jwt.Scheme)
                .RequireAuthenticatedUser())
            .AddPolicy(V3DA04Policies.RemoveReview, policy => policy
                .AddRequirements(new ReviewRemovalRequirement()));
    }
