// v3da04_authorization_policies / ex8 - reference solution (author only, used by `dojo verify`).

using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Options;

namespace DotnetDojo.Api.V3DA04_AuthorizationPolicies;

public class PermissionPolicyProvider : IAuthorizationPolicyProvider
{
    public const string Prefix = "permission:";

    public static int Built;

    private readonly DefaultAuthorizationPolicyProvider _fallback;

    public PermissionPolicyProvider(IOptions<AuthorizationOptions> options)
    {
        _fallback = new DefaultAuthorizationPolicyProvider(options);
    }

    public Task<AuthorizationPolicy> GetDefaultPolicyAsync() =>
        _fallback.GetDefaultPolicyAsync();

    public Task<AuthorizationPolicy?> GetFallbackPolicyAsync() =>
        _fallback.GetFallbackPolicyAsync();

    public Task<AuthorizationPolicy?> GetPolicyAsync(string policyName)
    {
        // Never return null for names you do not recognise: that would delete
        // every conventionally registered policy in the application.
        if (!policyName.StartsWith(Prefix, StringComparison.Ordinal))
        {
            return _fallback.GetPolicyAsync(policyName);
        }

        Interlocked.Increment(ref Built);

        var permission = policyName[Prefix.Length..];

        // A fresh policy per call: cheap, and safe on a singleton that may be
        // asked concurrently.
        var policy = new AuthorizationPolicyBuilder()
            .AddAuthenticationSchemes(V3DA04Jwt.Scheme)
            .RequireAuthenticatedUser()
            .RequireClaim("perm", permission)
            .Build();

        return Task.FromResult<AuthorizationPolicy?>(policy);
    }
}

public class Ex8Services : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<IAuthorizationPolicyProvider, PermissionPolicyProvider>();

        services.AddAuthorizationBuilder()
            .AddPolicy(V3DA04Policies.PanelMember, policy => policy
                .AddAuthenticationSchemes(V3DA04Jwt.Scheme)
                .RequireAuthenticatedUser()
                .RequireClaim("panel"));
    }
}

public class Ex8 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var perm = app.MapGroup("/v3da04/perm").WithTags("v3da04");

        perm.MapGet("/read", () => TypedResults.Ok(V3DA04Board.Proposals
                .OrderBy(p => p.Id)
                .Select(p => new { id = p.Id, title = p.Title })
                .ToList()))
            .RequireAuthorization($"{PermissionPolicyProvider.Prefix}proposal.read");

        perm.MapPost("/score/{id:int}", Score)
            .RequireAuthorization($"{PermissionPolicyProvider.Prefix}proposal.score");

        perm.MapGet("/panel", () => TypedResults.Ok(new { panel = true }))
            .RequireAuthorization(V3DA04Policies.PanelMember);

        perm.MapGet("/built", () => TypedResults.Ok(new { built = PermissionPolicyProvider.Built }))
            .AllowAnonymous();
    }

    private static IResult Score(int id) =>
        V3DA04Board.Find(id) is null ? TypedResults.NotFound() : TypedResults.NoContent();
}

