// v3da04_authorization_policies / challenge - reference solution (author only, used by `dojo verify`).

using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;

namespace DotnetDojo.Api.V3DA04_AuthorizationPolicies;

public record Decision(string Outcome, string? Note);

public class PanelChairHandler : AuthorizationHandler<DecisionRequirement, Proposal>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context, DecisionRequirement requirement, Proposal resource)
    {
        if (context.User.IsInRole("chair") && context.User.HasClaim("panel", resource.Panel))
        {
            context.Succeed(requirement);
        }

        return Task.CompletedTask;
    }
}

public class DelegatedDeciderHandler : AuthorizationHandler<DecisionRequirement, Proposal>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context, DecisionRequirement requirement, Proposal resource)
    {
        var sub = context.User.FindFirst("sub")?.Value;

        if (sub is not null && resource.Deciders.Contains(sub))
        {
            context.Succeed(requirement);
        }

        return Task.CompletedTask;
    }
}

public class SealedProposalHandler : AuthorizationHandler<DecisionRequirement, Proposal>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context, DecisionRequirement requirement, Proposal resource)
    {
        if (resource.Sealed)
        {
            context.Fail(new AuthorizationFailureReason(this, "The proposal is sealed."));
        }

        return Task.CompletedTask;
    }
}

public class ChallengeServices : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<IAuthorizationPolicyProvider, PermissionPolicyProvider>();
        services.AddSingleton<IAuthorizationHandler, PanelChairHandler>();
        services.AddSingleton<IAuthorizationHandler, DelegatedDeciderHandler>();
        services.AddSingleton<IAuthorizationHandler, SealedProposalHandler>();

        services.AddAuthorizationBuilder()
            .AddPolicy(V3DA04Policies.DecideProposal, policy => policy
                .AddRequirements(new DecisionRequirement()));
    }
}

public class Challenge : IEndpointMapper
{
    private static readonly string[] Outcomes = ["fund", "reject", "defer"];

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3da04/board/proposals/{id:int}/decision", Decide)
            // Answerable from the token alone, so the middleware can do it.
            .RequireAuthorization($"{PermissionPolicyProvider.Prefix}proposal.decide")
            .WithTags("v3da04");
    }

    private static async Task<IResult> Decide(
        int id,
        Decision body,
        ClaimsPrincipal user,
        IAuthorizationService authorization)
    {
        var proposal = V3DA04Board.Find(id);
        if (proposal is null)
        {
            return TypedResults.NotFound();
        }

        var decision = await authorization.AuthorizeAsync(
            user, proposal, V3DA04Policies.DecideProposal);

        if (!decision.Succeeded)
        {
            // Empty when the failure was a pending requirement rather than a
            // veto - which is a meaningful difference, so it is not hidden.
            var reasons = decision.Failure?.FailureReasons
                .Select(r => r.Message)
                .Order(StringComparer.Ordinal)
                .ToArray() ?? [];

            return TypedResults.Problem(
                title: "Not permitted",
                statusCode: 403,
                extensions: new Dictionary<string, object?> { ["reasons"] = reasons });
        }

        if (!Outcomes.Contains(body.Outcome))
        {
            return TypedResults.ValidationProblem(
                new Dictionary<string, string[]> { ["outcome"] = ["fund, reject or defer."] },
                statusCode: 422);
        }

        if (proposal.Outcome is not null)
        {
            return TypedResults.Problem(title: "Already decided", statusCode: 409);
        }

        proposal.Outcome = body.Outcome;

        return TypedResults.Ok(new
        {
            id = proposal.Id,
            outcome = proposal.Outcome,
            decidedBy = user.FindFirst("sub")?.Value,
        });
    }
}

