// v3da04_authorization_policies / review1 - reference solution (author only, used by `dojo verify`).

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Authorization.Policy;

namespace DotnetDojo.Api.V3DA04_AuthorizationPolicies;

public class BoardAuthorizationResultHandler : IAuthorizationMiddlewareResultHandler
{
    private readonly AuthorizationMiddlewareResultHandler _inner = new();

    public async Task HandleAsync(
        RequestDelegate next,
        HttpContext context,
        AuthorizationPolicy policy,
        PolicyAuthorizationResult authorizeResult)
    {
        // Challenges belong to the scheme: it writes the status and the
        // WWW-Authenticate header a client needs in order to try again.
        if (!authorizeResult.Forbidden)
        {
            await _inner.HandleAsync(next, context, policy, authorizeResult);

            return;
        }

        var policyName = context.GetEndpoint()?.Metadata
            .GetOrderedMetadata<IAuthorizeData>()
            .Select(d => d.Policy)
            .FirstOrDefault(p => !string.IsNullOrEmpty(p)) ?? "default";

        var requirements = authorizeResult.AuthorizationFailure?.FailedRequirements
            .Select(r => r.GetType().Name)
            .Order(StringComparer.Ordinal)
            .ToArray() ?? [];

        context.Response.StatusCode = StatusCodes.Status403Forbidden;
        context.Response.ContentType = "application/problem+json";

        await context.Response.WriteAsJsonAsync(new
        {
            title = "Not permitted",
            status = 403,
            policy = policyName,
            requirements,
        });
    }
}

public class Review1Services : IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<IAuthorizationHandler, SeniorityHandler>();
        services.AddSingleton<IAuthorizationMiddlewareResultHandler,
            BoardAuthorizationResultHandler>();

        services.AddAuthorizationBuilder()
            .AddPolicy(V3DA04Policies.Senior, policy => policy
                .AddAuthenticationSchemes(V3DA04Jwt.Scheme)
                .RequireAuthenticatedUser()
                .AddRequirements(new SeniorityRequirement(5)));
    }
}

public class Review1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var report = app.MapGroup("/v3da04/report").WithTags("v3da04");

        report.MapGet("/proposals", () => TypedResults.Ok(V3DA04Board.Proposals
                .OrderBy(p => p.Id)
                .Select(p => new { id = p.Id, title = p.Title, panel = p.Panel })
                .ToList()))
            .RequireAuthorization(V3DA04Policies.Senior);

        report.MapGet("/open", () => TypedResults.Ok(new { open = true }))
            .AllowAnonymous();
    }
}

lessons.fullReadme:
# V3·DA5 — API versioning and evolving a contract

## 1. The change taxonomy

| change | breaking? | notes |
|---|---|---|
| add a response field | no | requires tolerant readers |
| add an optional request field | no | needs a default that preserves behaviour |
| add an endpoint | no | |
| rename a field | **yes** | the classic |
| change a field's type | **yes** | including `int` → `string` id |
| remove a field | **yes** | even one you think nobody uses |
| make an optional field required | **yes** | |
| tighten validation | **yes** | previously accepted input now 400s |
| add an enum value | **maybe** | safe if clients filter, breaking if they switch |
| change a default | **maybe** | almost always breaks somebody |
| change sort order | **maybe** | if it was ever stable, it was a contract |
| change a status code | **yes** | clients branch on these |

The "maybe" rows are where judgement lives, and the deciding question is always
the same: what does a reasonable client do with this, and does that still work?

## 2. Path versioning

```csharp
var v1 = app.MapGroup("/v3da05/v1").WithTags("v3da05-v1");
var v2 = app.MapGroup("/v3da05/v2").WithTags("v3da05-v2");

v1.MapGet("/lanes", ListLanes);      // identical in both versions
v2.MapGet("/lanes", ListLanes);

v1.MapGet("/quotes/{id:int}", GetQuoteV1);
v2.MapGet("/quotes/{id:int}", GetQuoteV2);
```

Cheap, explicit, cache-friendly, and the group is a natural home for per-version
conventions such as deprecation headers.

## 3. Header and query versioning

```csharp
public static class VersionSelector
{
    public const string ItemKey = "v3da05-version";
    public static readonly int[] Supported = [1, 2];

    public static EndpointFilterDelegate Filter(EndpointFilterDelegate next) =>
        async context =>
        {
            var http = context.HttpContext;
            var header = http.Request.Headers["X-Api-Version"].ToString();
            var query = http.Request.Query["api-version"].ToString();

            if (!string.IsNullOrEmpty(header) && !string.IsNullOrEmpty(query)
                && header != query)
            {
                return TypedResults.Problem(
                    title: "Conflicting API versions", statusCode: 400);
            }

            var raw = string.IsNullOrEmpty(header) ? query : header;
            var version = string.IsNullOrEmpty(raw) ? 1 : int.TryParse(raw, out var v) ? v : -1;

            if (!Supported.Contains(version))
            {
                return TypedResults.Problem(
                    title: "Unsupported API version", statusCode: 400,
                    extensions: new Dictionary<string, object?>
                    {
                        ["requested"] = raw, ["supported"] = Supported,
                    });
            }

            http.Items[ItemKey] = version;
            http.Response.Headers["api-supported-versions"] = string.Join(",", Supported);
            return await next(context);
        };
}
```

Note the `api-supported-versions` response header: it is what the versioning
library emits, and it lets a client discover the range without reading docs.

Anything that varies by a header must also say so:

```csharp
http.Response.Headers.Vary = "X-Api-Version";
```

## 4. Media-type versioning

```csharp
static int? FromAccept(HttpRequest request)
{
    foreach (var raw in request.Headers.Accept)
    {
        if (!MediaTypeHeaderValue.TryParse(raw, out var media)) continue;
        if (media.MediaType != "application/json" && media.MediaType != "*/*") continue;

        var parameter = media.Parameters
            .FirstOrDefault(p => p.Name.Equals("v", StringComparison.OrdinalIgnoreCase));

        if (parameter is null) return null;                     // unversioned
        return int.TryParse(parameter.Value?.Value, out var v) ? v : -1;
    }
    return null;
}
```

Unsupported version here is **406**, because the client asked for a
representation you cannot produce.

## 5. Adapters

```csharp
public record Quote(int Id, string Lane, decimal BaseRate,
                    decimal Surcharge, string Currency, DateOnly ValidUntil);

public record QuoteV1(int id, string lane, decimal rate, string currency);
public record QuoteV2(int id, string lane, decimal baseRate, decimal surcharge,
                      decimal total, string currency, string validUntil);

public static class QuoteAdapters
{
    // v1 promised one combined "rate" and no expiry. Keep that promise here,
    // once, instead of in every handler.
    public static QuoteV1 ToV1(Quote q) =>
        new(q.Id, q.Lane, q.BaseRate + q.Surcharge, q.Currency);

    public static QuoteV2 ToV2(Quote q) =>
        new(q.Id, q.Lane, q.BaseRate, q.Surcharge, q.BaseRate + q.Surcharge,
            q.Currency, q.ValidUntil.ToString("O"));
}
```

One handler, one domain object, a `switch` at the edge:

```csharp
private static IResult GetQuote(int id, HttpContext http)
{
    var quote = Rates.Find(id);
    if (quote is null) return TypedResults.NotFound();

    return Version(http) switch
    {
        1 => TypedResults.Ok<object>(QuoteAdapters.ToV1(quote)),
        _ => TypedResults.Ok<object>(QuoteAdapters.ToV2(quote)),
    };
}
```

## 6. Deprecating and retiring

```csharp
var v1 = app.MapGroup("/v3da05/v1")
    .AddEndpointFilter(async (context, next) =>
    {
        var headers = context.HttpContext.Response.Headers;
        headers["Deprecation"] = "Wed, 01 Jan 2025 00:00:00 GMT";
        headers["Sunset"] = "Tue, 01 Jul 2025 00:00:00 GMT";
        headers["Link"] = "</v3da05/docs/migrate-v2>; rel=\"deprecation\"";
        return await next(context);
    });
```

and, after the sunset date:

```csharp
app.Map("/v3da05/v1/{**rest}", () => TypedResults.Problem(
    title: "API version 1 has been retired",
    statusCode: StatusCodes.Status410Gone,
    extensions: new Dictionary<string, object?>
    {
        ["successor"] = "/v3da05/v2",
        ["retiredOn"] = "2025-07-01",
    }));
```

Keeping the route mapped is deliberate: 404 makes a client doubt their URL, 410
tells them to upgrade.

## 7. The default-version question

| policy | behaviour | cost |
|---|---|---|
| latest | unversioned requests follow your releases | breaks lazy clients on every release |
| oldest | unversioned requests are frozen | new clients silently get old behaviour |
| refuse | unversioned requests get 400 | breaks the first `curl` anybody tries |

"Oldest" is the usual answer for public APIs, because the client who did not
specify is the client least able to cope with change. "Refuse" is the right
answer for internal APIs, where you can mandate it. "Latest" is defensible only
while you have one client.

## 8. Common mistakes

1. **Duplicating handlers per version.** They diverge, and a fix lands in one.
2. **Versioning per endpoint.** `/quotes/v2` next to `/lanes/v1` is a matrix
   nobody can reason about; version the API, not the resource.
3. **Forgetting `Vary`.** Header-versioned responses get cached across versions.
4. **404 for a retired version.** Tells the client nothing.
5. **Bumping the version for an additive change.** Doubles your maintenance for
   nothing.
6. **No default policy.** Then the default is whatever the code happens to do.
7. **Versioning the error contract too.** Problem details should be stable
   across versions; a client's error handling should not need a rewrite.
8. **A version number in the type name only.** `QuoteV2` in a namespace but no
   route or header change means clients cannot ask for it.

## 9. The interview answer

> *"How do you version an HTTP API?"*

First by not needing to: additive changes — new fields, new optional inputs, new
endpoints — are safe for tolerant readers, and designing so that most change is
additive is worth more than any versioning scheme. When a breaking change is
unavoidable, I put the version in the path, because it is visible in logs,
pasteable into a ticket, and cacheable without `Vary` games; header or media-type
versioning is more correct by HTTP's model and worse in practice. One
implementation over a current domain model, with a per-version adapter mapping to
the shape that version promised, so retiring a version deletes one file. Then a
lifecycle: `Deprecation` and `Sunset` headers with a `Link` to the migration
guide, a defined default for unversioned requests, and a 410 with a successor
pointer once it is gone.

## 10. Check yourself

1. Give three changes that are safe and three that are breaking.
2. Why is "add a field" safe, and what client behaviour is that claim resting on?
3. Name the three places a version can live, with one advantage each.
4. What response header must a header-versioned API set, and what breaks without
   it?
5. Which status code for an unsupported version in a header? In `Accept`? Why do
   they differ?
6. What should a request carrying two conflicting version indicators receive?
7. What is the adapter pattern here, and what problem does it solve at three
   versions?
8. Which two headers signal deprecation, and what type are their values?
9. Why 410 rather than 404 for a retired version?
10. State the three default-version policies and who each one hurts.
11. Why should the error contract not be versioned alongside the payload?
12. When does adding an enum value break a client?

