// v3da05_api_versioning / ex1 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public record Quote(
    int Id, string Lane, decimal BaseRate, decimal Surcharge, string Currency, DateOnly ValidUntil)
{
    public decimal Total => BaseRate + Surcharge;
}

public static class V3DA05Rates
{
    public static readonly string[] Lanes = ["FEL-RTM", "RTM-SIN", "SIN-LAX"];

    public static readonly List<Quote> Quotes =
    [
        new(1, "FEL-RTM", 1200.00m, 250.00m, "EUR", new DateOnly(2026, 3, 31)),
        new(2, "RTM-SIN", 2450.00m, 310.00m, "USD", new DateOnly(2026, 4, 15)),
        new(3, "SIN-LAX", 1875.00m, 125.00m, "USD", new DateOnly(2026, 5, 1)),
    ];

    public static Quote? Find(int id) => Quotes.FirstOrDefault(q => q.Id == id);
}

public static class QuoteAdapters
{
    // v1 promised one combined rate and no expiry. The promise is kept here,
    // once, rather than in every handler that serves a v1 client.
    public static object ToV1(Quote q) => new
    {
        id = q.Id,
        lane = q.Lane,
        rate = q.Total,
        currency = q.Currency,
    };

    public static object ToV2(Quote q) => new
    {
        id = q.Id,
        lane = q.Lane,
        baseRate = q.BaseRate,
        surcharge = q.Surcharge,
        total = q.Total,
        currency = q.Currency,
        validUntil = q.ValidUntil.ToString("yyyy-MM-dd"),
    };
}

public class Ex1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var v1 = app.MapGroup("/v3da05/v1").WithTags("v3da05-v1");
        var v2 = app.MapGroup("/v3da05/v2").WithTags("v3da05-v2");

        // Unchanged between versions: one method, two endpoints.
        v1.MapGet("/lanes", ListLanes);
        v2.MapGet("/lanes", ListLanes);

        v1.MapGet("/quotes/{id:int}", (int id) => Get(id, QuoteAdapters.ToV1));
        v2.MapGet("/quotes/{id:int}", (int id) => Get(id, QuoteAdapters.ToV2));
    }

    private static IResult ListLanes() =>
        TypedResults.Ok(new { lanes = V3DA05Rates.Lanes.Order(StringComparer.Ordinal).ToList() });

    private static IResult Get(int id, Func<Quote, object> adapt)
    {
        var quote = V3DA05Rates.Find(id);

        return quote is null ? TypedResults.NotFound() : TypedResults.Ok(adapt(quote));
    }
}

