// v3da05_api_versioning / ex2 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public class Ex2 : IEndpointMapper
{
    public const string ItemKey = "v3da05-version";

    private static readonly int[] Supported = [1, 2];

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var api = app.MapGroup("/v3da05")
            .WithTags("v3da05")
            .AddEndpointFilter(async (context, next) =>
            {
                var http = context.HttpContext;

                // Before any early return: an error response must also declare
                // what it varied on.
                http.Response.Headers.Vary = "X-Api-Version";

                var header = http.Request.Headers["X-Api-Version"].ToString();
                var query = http.Request.Query["api-version"].ToString();

                if (header.Length > 0 && query.Length > 0
                    && !string.Equals(header, query, StringComparison.Ordinal))
                {
                    return TypedResults.Problem(
                        title: "Conflicting API versions",
                        statusCode: 400,
                        extensions: new Dictionary<string, object?>
                        {
                            ["header"] = header,
                            ["query"] = query,
                        });
                }

                var raw = header.Length > 0 ? header : query;

                var version = raw.Length == 0
                    ? 1
                    : int.TryParse(raw, out var parsed) ? parsed : -1;

                if (!Supported.Contains(version))
                {
                    return TypedResults.Problem(
                        title: "Unsupported API version",
                        statusCode: 400,
                        extensions: new Dictionary<string, object?>
                        {
                            ["requested"] = raw,
                            ["supported"] = Supported,
                        });
                }

                http.Items[ItemKey] = version;
                http.Response.Headers["api-supported-versions"] = "1,2";

                return await next(context);
            });

        api.MapGet("/quotes/{id:int}", GetQuote);
    }

    public static int VersionOf(HttpContext http) => (int)(http.Items[ItemKey] ?? 1);

    private static IResult GetQuote(int id, HttpContext http)
    {
        var quote = V3DA05Rates.Find(id);
        if (quote is null)
        {
            return TypedResults.NotFound();
        }

        return VersionOf(http) == 1
            ? TypedResults.Ok(QuoteAdapters.ToV1(quote))
            : TypedResults.Ok(QuoteAdapters.ToV2(quote));
    }
}

