// v3da05_api_versioning / ex3 - reference solution (author only, used by `dojo verify`).

using Microsoft.Net.Http.Headers;

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public class Ex3 : IEndpointMapper
{
    private static readonly int[] Supported = [1, 2];

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da05/media/quotes/{id:int}", GetQuote).WithTags("v3da05");
    }

    private static IResult GetQuote(int id, HttpContext http)
    {
        var (version, problem) = Negotiate(http.Request);
        if (problem is not null)
        {
            return problem;
        }

        var quote = V3DA05Rates.Find(id);
        if (quote is null)
        {
            return TypedResults.NotFound();
        }

        http.Response.ContentType = $"application/json; v={version}";

        return version == 1
            ? TypedResults.Ok(QuoteAdapters.ToV1(quote))
            : TypedResults.Ok(QuoteAdapters.ToV2(quote));
    }

    private static (int Version, IResult? Problem) Negotiate(HttpRequest request)
    {
        var accept = request.Headers.Accept;

        // No opinion from the client: give them the default representation.
        if (accept.Count == 0 || !MediaTypeHeaderValue.TryParseList(accept, out var candidates))
        {
            return (1, null);
        }

        foreach (var candidate in candidates)
        {
            var type = candidate.MediaType.Value;

            if (type != "application/json" && type != "*/*")
            {
                // A format we cannot produce is skipped, not fatal: Accept is an
                // ordered list of acceptable alternatives.
                continue;
            }

            var parameter = candidate.Parameters.FirstOrDefault(p =>
                p.Name.Equals("v", StringComparison.OrdinalIgnoreCase));

            if (parameter is null)
            {
                return (1, null);
            }

            var raw = parameter.Value.Value ?? string.Empty;

            if (int.TryParse(raw, out var version) && Supported.Contains(version))
            {
                return (version, null);
            }

            return (0, TypedResults.Problem(
                title: "Unsupported representation",
                statusCode: 406,
                extensions: new Dictionary<string, object?>
                {
                    ["requested"] = raw,
                    ["supported"] = Supported,
                }));
        }

        return (0, TypedResults.Problem(
            title: "Only application/json is available",
            statusCode: 406));
    }
}

