// v3da05_api_versioning / ex4 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public record QuoteRequest(string Lane, int Weight, string? ServiceLevel);

public class Ex4 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var additive = app.MapGroup("/v3da05/additive").WithTags("v3da05");

        additive.MapPost("/quotes", CreateQuote);
        additive.MapGet("/contract/{version:int}", Contract);
    }

    private static IResult CreateQuote(QuoteRequest body, HttpContext http)
    {
        // Absent means exactly what the previous behaviour was. If "standard"
        // priced differently from "unspecified", this would be a breaking change
        // dressed as an optional field.
        var level = body.ServiceLevel ?? "standard";

        if (level is not ("standard" or "express"))
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["serviceLevel"] = ["standard or express."],
            });
        }

        if (!V3DA05Rates.Lanes.Contains(body.Lane))
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["lane"] = ["Unknown lane."],
            });
        }

        if (body.Weight < 1)
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["weight"] = ["Must be positive."],
            });
        }

        var quote = Price(body, level);

        return Ex2.VersionOf(http) == 1
            ? TypedResults.Ok(WithCarbon(QuoteAdapters.ToV1(quote), quote))
            : TypedResults.Ok(WithCarbon(QuoteAdapters.ToV2(quote), quote));
    }

    private static IResult Contract(int version)
    {
        var quote = V3DA05Rates.Quotes[0];

        var shaped = version == 1
            ? WithCarbon(QuoteAdapters.ToV1(quote), quote)
            : WithCarbon(QuoteAdapters.ToV2(quote), quote);

        var members = shaped.GetType()
            .GetProperties()
            .Select(p => p.Name)
            .Order(StringComparer.Ordinal)
            .ToList();

        return TypedResults.Ok(new { version, members });
    }

    private static Quote Price(QuoteRequest body, string level)
    {
        var baseRate = 1200.00m + body.Weight * 0.25m;
        var surcharge = 250.00m * (level == "express" ? 2 : 1);

        return new Quote(4, body.Lane, baseRate, surcharge, "EUR", new DateOnly(2026, 3, 31));
    }

    // The additive member, present in both shapes: a client that has never heard
    // of carbonKg ignores it and keeps working.
    private static object WithCarbon(object shape, Quote quote) => shape switch
    {
        _ => Merge(shape, new { carbonKg = decimal.Round(quote.Total * 0.2155m, 1) }),
    };

    private static object Merge(object left, object right)
    {
        var members = new Dictionary<string, object?>();

        foreach (var property in left.GetType().GetProperties())
        {
            members[property.Name] = property.GetValue(left);
        }

        foreach (var property in right.GetType().GetProperties())
        {
            members[property.Name] = property.GetValue(right);
        }

        return members;
    }
}

exercises.hints:
## Hint 1

You have a `switch` that grows by one arm per version. Replace it with a lookup
that grows by one entry per version, and notice which parts of the handler stop
changing.

## Hint 2

A dispatch table of projections:

    private static readonly Dictionary<int, Func<Shipment, object>> Shapes = new()
    {
        [1] = s => new ShipmentV1(s.Id, s.Weight),
        [2] = s => new ShipmentV2(s.Id, s.Weight, s.Volume),
    };

    if (!Shapes.TryGetValue(version, out var shape)) return Unsupported(version);
    return TypedResults.Ok(shape(item));

The supported set and the dispatch table are now the same object, which means
they cannot disagree.

## Hint 3

`QuoteV3`'s `Components` is `[new Money(q.BaseRate, q.Currency), new
Money(q.Surcharge, q.Currency)]`. The decision left to you: should the id
transformation `q-{n}` live in the adapter, or should `Quote` gain a string id
that v1 and v2 adapters parse back to an int? One of those makes v4 easier.

