// v3da05_api_versioning / ex5 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public record Money(decimal Amount, string Currency);

public record QuoteV1(int Id, string Lane, decimal Rate, string Currency);

public record QuoteV2(
    int Id, string Lane, decimal BaseRate, decimal Surcharge,
    decimal Total, string Currency, string ValidUntil);

public record QuoteV3(
    string Id, string Lane, Money Total, Money[] Components, string ValidUntil);

public class Ex5 : IEndpointMapper
{
    // The dispatch table and the supported set are the same object, so they
    // cannot drift apart.
    private static readonly Dictionary<int, Func<Quote, object>> Shapes = new()
    {
        [1] = q => new QuoteV1(q.Id, q.Lane, q.Total, q.Currency),

        [2] = q => new QuoteV2(
            q.Id, q.Lane, q.BaseRate, q.Surcharge, q.Total, q.Currency,
            q.ValidUntil.ToString("yyyy-MM-dd")),

        [3] = q => new QuoteV3(
            $"q-{q.Id}",
            q.Lane,
            new Money(q.Total, q.Currency),
            [new Money(q.BaseRate, q.Currency), new Money(q.Surcharge, q.Currency)],
            q.ValidUntil.ToString("yyyy-MM-dd")),
    };

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var adapt = app.MapGroup("/v3da05/adapt").WithTags("v3da05");

        adapt.MapGet("/quotes/{id:int}", GetQuote);
        adapt.MapGet("/versions", () =>
            TypedResults.Ok(new { versions = Shapes.Keys.Order().ToList() }));
    }

    private static IResult GetQuote(int id, HttpContext http)
    {
        http.Response.Headers.Vary = "X-Api-Version";

        var raw = http.Request.Headers["X-Api-Version"].ToString();
        var version = raw.Length == 0 ? 1 : int.TryParse(raw, out var v) ? v : -1;

        // The handler does not know how many versions exist; it looks one up.
        if (!Shapes.TryGetValue(version, out var shape))
        {
            return TypedResults.Problem(
                title: "Unsupported API version",
                statusCode: 400,
                extensions: new Dictionary<string, object?>
                {
                    ["requested"] = raw,
                    ["supported"] = Shapes.Keys.Order().ToArray(),
                });
        }

        var quote = V3DA05Rates.Find(id);

        return quote is null ? TypedResults.NotFound() : TypedResults.Ok(shape(quote));
    }
}

