// v3da05_api_versioning / ex6 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public class Ex6 : IEndpointMapper
{
    private static readonly DateTimeOffset DeprecatedOn = new(2025, 1, 1, 0, 0, 0, TimeSpan.Zero);
    private static readonly DateTimeOffset SunsetOn = new(2025, 7, 1, 0, 0, 0, TimeSpan.Zero);

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var lifecycle = app.MapGroup("/v3da05/lifecycle")
            .WithTags("v3da05")
            .AddEndpointFilter(async (context, next) =>
            {
                context.HttpContext.Response.Headers["api-supported-versions"] = "1,2,3";

                return await next(context);
            });

        var v1 = lifecycle.MapGroup("/v1").AddEndpointFilter(async (context, next) =>
        {
            // Set before next: a 404 from a deprecated version is still a
            // response that should carry the announcement.
            var headers = context.HttpContext.Response.Headers;
            headers["Deprecation"] = DeprecatedOn.ToString("R");
            headers["Sunset"] = SunsetOn.ToString("R");
            headers["Link"] =
                "</v3da05/lifecycle/docs/v1-to-v3>; rel=\"deprecation\"; type=\"text/html\"";
            headers["api-deprecated-versions"] = "1";

            return await next(context);
        });

        var v2 = lifecycle.MapGroup("/v2");
        var v3 = lifecycle.MapGroup("/v3");

        v1.MapGet("/quotes/{id:int}", (int id) => Get(id, 1));
        v2.MapGet("/quotes/{id:int}", (int id) => Get(id, 2));
        v3.MapGet("/quotes/{id:int}", (int id) => Get(id, 3));

        lifecycle.MapGet("/versions", () => TypedResults.Ok(new
        {
            versions = new object[]
            {
                new { version = 1, status = "deprecated", sunset = "2025-07-01" },
                new { version = 2, status = "supported", sunset = (string?)null },
                new { version = 3, status = "current", sunset = (string?)null },
            },
        }));
    }

    private static IResult Get(int id, int version)
    {
        var quote = V3DA05Rates.Find(id);
        if (quote is null)
        {
            return TypedResults.NotFound();
        }

        // A deprecated version still works, exactly as it always did.
        return version switch
        {
            1 => TypedResults.Ok<object>(new QuoteV1(quote.Id, quote.Lane, quote.Total, quote.Currency)),
            2 => TypedResults.Ok<object>(new QuoteV2(
                quote.Id, quote.Lane, quote.BaseRate, quote.Surcharge, quote.Total,
                quote.Currency, quote.ValidUntil.ToString("yyyy-MM-dd"))),
            _ => TypedResults.Ok<object>(new QuoteV3(
                $"q-{quote.Id}", quote.Lane, new Money(quote.Total, quote.Currency),
                [new Money(quote.BaseRate, quote.Currency), new Money(quote.Surcharge, quote.Currency)],
                quote.ValidUntil.ToString("yyyy-MM-dd"))),
        };
    }
}

