// v3da05_api_versioning / ex8 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public enum DefaultVersionPolicy
{
    Latest,
    Oldest,
    Refuse,
}

public class Ex8 : IEndpointMapper
{
    private static readonly int[] Supported = [1, 2, 3];

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/v3da05/default").WithTags("v3da05");

        group.MapGet("/{policy}/quotes/{id:int}", GetQuote);

        group.MapGet("/policies", () => TypedResults.Ok(new
        {
            policies = new object[]
            {
                new { policy = "latest", unversionedGets = (int?)3, breaksOnRelease = true },
                new { policy = "oldest", unversionedGets = (int?)1, breaksOnRelease = false },
                new { policy = "refuse", unversionedGets = (int?)null, breaksOnRelease = false },
            },
        }));
    }

    private static IResult GetQuote(string policy, int id, HttpContext http)
    {
        http.Response.Headers.Vary = "X-Api-Version";

        var chosen = policy switch
        {
            "latest" => DefaultVersionPolicy.Latest,
            "oldest" => DefaultVersionPolicy.Oldest,
            "refuse" => DefaultVersionPolicy.Refuse,
            _ => (DefaultVersionPolicy?)null,
        };

        if (chosen is null)
        {
            return TypedResults.NotFound();
        }

        var raw = http.Request.Headers["X-Api-Version"].ToString();

        int version;
        string source;

        if (raw.Length > 0)
        {
            if (!int.TryParse(raw, out version) || !Supported.Contains(version))
            {
                return TypedResults.Problem(
                    title: "Unsupported API version",
                    statusCode: 400,
                    extensions: new Dictionary<string, object?>
                    {
                        ["requested"] = raw,
                        ["supported"] = Supported,
                    });
            }

            source = "request";
        }
        else
        {
            switch (chosen)
            {
                case DefaultVersionPolicy.Latest:
                    // Max(), not a literal: adding v4 must move the default.
                    version = Supported.Max();
                    source = "default-latest";
                    break;

                case DefaultVersionPolicy.Oldest:
                    version = Supported.Min();
                    source = "default-oldest";
                    break;

                default:
                    return TypedResults.Problem(
                        title: "An API version is required",
                        statusCode: 400,
                        extensions: new Dictionary<string, object?>
                        {
                            ["supported"] = Supported,
                            ["how"] = "Send X-Api-Version or ?api-version",
                        });
            }
        }

        var quote = V3DA05Rates.Find(id);
        if (quote is null)
        {
            return TypedResults.NotFound();
        }

        // Provenance, not just the value: a client can see what it got and why.
        http.Response.Headers["api-version"] = version.ToString();
        http.Response.Headers["api-version-source"] = source;

        return TypedResults.Ok(Shape(quote, version));
    }

    private static object Shape(Quote q, int version) => version switch
    {
        1 => new QuoteV1(q.Id, q.Lane, q.Total, q.Currency),
        2 => new QuoteV2(q.Id, q.Lane, q.BaseRate, q.Surcharge, q.Total, q.Currency,
            q.ValidUntil.ToString("yyyy-MM-dd")),
        _ => new QuoteV3($"q-{q.Id}", q.Lane, new Money(q.Total, q.Currency),
            [new Money(q.BaseRate, q.Currency), new Money(q.Surcharge, q.Currency)],
            q.ValidUntil.ToString("yyyy-MM-dd")),
    };
}

