// v3da05_api_versioning / challenge - reference solution (author only, used by `dojo verify`).

using System.Diagnostics;

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public record QuoteRequestV3(string Lane, int Weight, string? ServiceLevel, string? Currency);

public class Challenge : IEndpointMapper
{
    private static readonly int[] Supported = [1, 2, 3];
    private static readonly DateTimeOffset DeprecatedOn = new(2025, 1, 1, 0, 0, 0, TimeSpan.Zero);
    private static readonly DateTimeOffset SunsetOn = new(2025, 7, 1, 0, 0, 0, TimeSpan.Zero);

    private const string ItemKey = "v3da05-full-version";

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var full = app.MapGroup("/v3da05/full")
            .WithTags("v3da05")
            .AddEndpointFilter(async (context, next) =>
            {
                var http = context.HttpContext;
                http.Response.Headers.Vary = "X-Api-Version";
                http.Response.Headers["api-supported-versions"] = "1,2,3";

                var header = http.Request.Headers["X-Api-Version"].ToString();
                var query = http.Request.Query["api-version"].ToString();

                if (header.Length > 0 && query.Length > 0
                    && !string.Equals(header, query, StringComparison.Ordinal))
                {
                    return Problem(http, "Conflicting API versions", 400, 0,
                        new Dictionary<string, object?> { ["header"] = header, ["query"] = query });
                }

                var raw = header.Length > 0 ? header : query;

                // Default: oldest. A client that did not choose is the client
                // least able to absorb a change.
                var version = raw.Length == 0
                    ? Supported.Min()
                    : int.TryParse(raw, out var parsed) ? parsed : -1;

                if (!Supported.Contains(version))
                {
                    return Problem(http, "Unsupported API version", 400, 0,
                        new Dictionary<string, object?>
                        {
                            ["requested"] = raw,
                            ["supported"] = Supported,
                        });
                }

                http.Items[ItemKey] = version;

                if (version == 1)
                {
                    // Before next, so a 422 carries them too.
                    var headers = http.Response.Headers;
                    headers["Deprecation"] = DeprecatedOn.ToString("R");
                    headers["Sunset"] = SunsetOn.ToString("R");
                    headers["Link"] =
                        "</v3da05/full/docs/v1-to-v3>; rel=\"deprecation\"; type=\"text/html\"";
                    headers["api-deprecated-versions"] = "1";
                }

                return await next(context);
            });

        full.MapPost("/quotes", Create);
    }

    private static IResult Create(QuoteRequestV3 body, HttpContext http)
    {
        var version = (int)http.Items[ItemKey]!;

        // Widest shape, oldest defaults: a v1 client under-sends and gets
        // exactly the behaviour it always had.
        var level = body.ServiceLevel ?? "standard";
        var currency = body.Currency ?? "EUR";

        var errors = Validate(body, level);
        if (errors.Count > 0)
        {
            return TypedResults.ValidationProblem(
                errors,
                statusCode: 422,
                title: "The quote was rejected.",
                extensions: Common(http, version));
        }

        var baseRate = 1200.00m + body.Weight * 0.25m;
        var surcharge = 250.00m * (level == "express" ? 2 : 1);
        var quote = new Quote(4, body.Lane, baseRate, surcharge, currency,
            new DateOnly(2026, 3, 31));

        return TypedResults.Ok(Shape(quote, version));
    }

    private static Dictionary<string, string[]> Validate(QuoteRequestV3 body, string level)
    {
        var errors = new Dictionary<string, string[]>();

        if (!V3DA05Rates.Lanes.Contains(body.Lane))
        {
            errors["lane"] = ["Unknown lane."];
        }

        if (body.Weight < 1)
        {
            errors["weight"] = ["Must be positive."];
        }

        // Checked under every version: a client sending this field means
        // something by it, and silently ignoring it prices their shipment wrong.
        if (level is not ("standard" or "express"))
        {
            errors["serviceLevel"] = ["standard or express."];
        }

        return errors;
    }

    private static object Shape(Quote q, int version) => version switch
    {
        1 => new QuoteV1(q.Id, q.Lane, q.Total, q.Currency),
        2 => new QuoteV2(q.Id, q.Lane, q.BaseRate, q.Surcharge, q.Total, q.Currency,
            q.ValidUntil.ToString("yyyy-MM-dd")),
        _ => new QuoteV3($"q-{q.Id}", q.Lane, new Money(q.Total, q.Currency),
            [new Money(q.BaseRate, q.Currency), new Money(q.Surcharge, q.Currency)],
            q.ValidUntil.ToString("yyyy-MM-dd")),
    };

    private static IResult Problem(
        HttpContext http, string title, int status, int version,
        Dictionary<string, object?>? extra = null)
    {
        var extensions = Common(http, version);

        foreach (var pair in extra ?? [])
        {
            extensions[pair.Key] = pair.Value;
        }

        return TypedResults.Problem(title: title, statusCode: status, extensions: extensions);
    }

    // The one thing that does not vary by version.
    private static Dictionary<string, object?> Common(HttpContext http, int version) => new()
    {
        ["apiVersion"] = version,
        ["traceId"] = Activity.Current?.Id ?? http.TraceIdentifier,
    };
}

