// v3da05_api_versioning / review1 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DA05_ApiVersioning;

public class Review1 : IEndpointMapper
{
    private static readonly Dictionary<string, string> Families = new(StringComparer.Ordinal)
    {
        ["pending"] = "open",
        ["disputed"] = "open",
        ["confirmed"] = "closed",
        ["expired"] = "closed",
    };

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var evolve = app.MapGroup("/v3da05/evolve").WithTags("v3da05");

        evolve.MapGet("/quotes", List);
        evolve.MapGet("/quotes/{id:int}", Get);
        evolve.MapGet("/statuses", Statuses);
    }

    private static IResult List(string? status)
    {
        // No membership check: an unknown value filters to nothing, which is
        // right for a client from the future and harmless for a typo. A 400 here
        // would break forward-compatible clients.
        var quotes = V3DA05Statuses.All
            .Where(q => status is null || q.Status == status)
            .OrderBy(q => q.Id)
            .Select(q => new { id = q.Id, status = q.Status, statusFamily = FamilyOf(q.Status) })
            .ToList();

        return TypedResults.Ok(quotes);
    }

    private static IResult Get(int id)
    {
        var quote = V3DA05Statuses.All.FirstOrDefault(q => q.Id == id);

        return quote is null
            ? TypedResults.NotFound()
            : TypedResults.Ok(new
            {
                id = quote.Id,
                status = quote.Status,
                statusFamily = FamilyOf(quote.Status),
            });
    }

    private static IResult Statuses() => TypedResults.Ok(new
    {
        statuses = Families.Keys.Order(StringComparer.Ordinal).ToList(),
        families = Families
            .GroupBy(pair => pair.Value)
            .OrderBy(g => g.Key, StringComparer.Ordinal)
            .ToDictionary(
                g => g.Key,
                g => g.Select(pair => pair.Key).Order(StringComparer.Ordinal).ToList()),

        // The documented promise that makes adding a value additive.
        openSet = true,
    });

    // The default arm is the point: a value added tomorrow still has a family
    // today, so a client switching on the coarse set never breaks.
    private static string FamilyOf(string status) =>
        Families.TryGetValue(status, out var family) ? family : "open";
}

lessons.fullReadme:
# V3·DA6 — OpenAPI, client generation and honest documentation

## 1. Where the document comes from

```csharp
var endpoints = app.Services.GetRequiredService<EndpointDataSource>();

foreach (var endpoint in endpoints.Endpoints.OfType<RouteEndpoint>())
{
    var path = endpoint.RoutePattern.RawText;
    var methods = endpoint.Metadata.GetMetadata<HttpMethodMetadata>()?.HttpMethods ?? [];
    var name = endpoint.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName;
    var responses = endpoint.Metadata.GetOrderedMetadata<IProducesResponseTypeMetadata>();
    var accepts = endpoint.Metadata.GetMetadata<IAcceptsMetadata>();
}
```

That is what every generator does. No handler is executed, no code path is
analysed. The document is exactly as truthful as the metadata.

## 2. Two ways to declare a response

```csharp
// Maintained by the compiler:
private static Results<Ok<SeedDto>, NotFound, ValidationProblem> GetSeed(string id) { … }

// Maintained by you:
app.MapGet("/v3da06/seeds/{id}", GetSeedUntyped)
   .Produces<SeedDto>(200)
   .Produces(404);
```

Both produce the same metadata. Only the first one breaks when the handler
changes. `Produces` is not wrong — it is necessary when the return type is
`IResult`, and for content types the union cannot express — but every call is a
promise you maintain by hand.

## 3. Reading metadata correctly

```csharp
// Wrong: returns the LAST matching item only.
var one = endpoint.Metadata.GetMetadata<IProducesResponseTypeMetadata>();

// Right:
var all = endpoint.Metadata.GetOrderedMetadata<IProducesResponseTypeMetadata>();
var codes = all.Select(m => m.StatusCode).Distinct().Order().ToArray();
```

This one-word difference is why a lint written in five minutes reports one
response per endpoint and looks like it is working.

## 4. A schema from a type

```csharp
static Dictionary<string, object?> SchemaOf(Type type)
{
    var nullability = new NullabilityInfoContext();
    var properties = new Dictionary<string, object?>();
    var required = new List<string>();

    foreach (var property in type.GetProperties())
    {
        var name = JsonNamingPolicy.CamelCase.ConvertName(property.Name);
        var underlying = Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;

        properties[name] = new Dictionary<string, object?>
        {
            ["type"] = JsonTypeOf(underlying),
        };

        var isNullable = Nullable.GetUnderlyingType(property.PropertyType) is not null
            || nullability.Create(property).ReadState is NullabilityState.Nullable;

        if (!isNullable) required.Add(name);
    }

    return new Dictionary<string, object?>
    {
        ["type"] = "object",
        ["properties"] = properties,
        ["required"] = required,
    };
}

static string JsonTypeOf(Type t) => t switch
{
    _ when t == typeof(string) => "string",
    _ when t == typeof(bool) => "boolean",
    _ when t == typeof(int) || t == typeof(long) => "integer",
    _ when t == typeof(decimal) || t == typeof(double) => "number",
    _ => "object",
};
```

`NullabilityInfoContext` is the only way to see `string?` versus `string` at
runtime, because reference nullability is an attribute rather than a type.

## 5. A minimal document

```json
{
  "openapi": "3.0.1",
  "info": { "title": "Seed bank", "version": "1.0.0" },
  "paths": {
    "/v3da06/seeds/{id}": {
      "get": {
        "operationId": "getSeed",
        "tags": ["seeds"],
        "summary": "Fetch one accession",
        "parameters": [
          { "name": "id", "in": "path", "required": true,
            "schema": { "type": "string" } }
        ],
        "responses": {
          "200": { "description": "OK",
            "content": { "application/json": {
              "schema": { "$ref": "#/components/schemas/SeedDto" } } } },
          "404": { "description": "Not Found",
            "content": { "application/problem+json": {
              "schema": { "$ref": "#/components/schemas/ProblemDetails" } } } }
        }
      }
    }
  },
  "components": { "schemas": { "SeedDto": { … }, "ProblemDetails": { … } } }
}
```

`responses` keys are **strings**, `description` is required by the specification
on every response, and `$ref` is what makes a generator emit one shared class.

## 6. Names are contract

```csharp
app.MapGet("/v3da06/seeds/{id}", GetSeed).WithName("getSeed");
```

`WithName` sets the endpoint name, which becomes the `operationId`, which becomes
a method name in every generated client. Therefore:

- always set it;
- never change it casually — renaming is a breaking change for generated clients,
  invisible to any test you own;
- keep it unique, or generation fails.

A convention that survives refactoring: `<verb><Resource>` — `listSeeds`,
`getSeed`, `createSeed`, `deleteSeed` — derived from intent, not from the route,
so moving a route does not rename a client method.

## 7. The lint

Run in CI, over the generated document:

| check | why |
|---|---|
| every operation has an `operationId` | otherwise generators invent unstable names |
| `operationId`s are unique | duplicates break generation |
| every operation has a `summary` | the one thing humans read |
| every operation declares its error responses | undeclared statuses become untyped exceptions |
| error responses `$ref` the shared schema | one error type in the client |
| no operation declares a status it cannot return | the drift that erodes trust |

The last one needs evidence from outside the document — tests, or the review
exercise's drift detector.

## 8. What a generated client looks like

The most useful review technique in this sector is to generate a client from your
own document and read it. For the seed bank, a well-documented API produces
something like:

```csharp
// Generated. Names come from operationId; types come from components/schemas.
public partial class SeedBankClient
{
    public Task<ICollection<SeedDto>> ListSeedsAsync(CancellationToken ct = default);
    public Task<SeedDto> GetSeedAsync(string id, CancellationToken ct = default);
    public Task<SeedDto> CreateSeedAsync(SeedRequest body, CancellationToken ct = default);
}

public partial class ApiException<TResult> : ApiException
{
    public TResult Result { get; }
}
```

with `ApiException<ProblemDetails>` thrown for the declared failures. Now read the
same generation from a badly documented API: `SeedsGetById` instead of
`GetSeedAsync`, `object` instead of `SeedDto`, and a bare `ApiException` carrying
a JSON string for every error.

Nothing about the server changed between those two outputs. The wire bytes are
identical. The entire difference is metadata — and it is the difference between
an integrator finishing in an afternoon and one filing questions for a week.

Two habits follow. Generate a client in CI and commit the generated file, so a
change to it appears in a pull-request diff: an unintended rename of a method or
a type becomes visible at review time rather than at a customer's build. And read
that file occasionally with a consumer's eyes; every `object`, every
`ApiException` with no type argument, and every method name you would not have
chosen is a piece of missing metadata with a name attached.

## 9. Common mistakes

1. **`GetMetadata` instead of `GetOrderedMetadata`.** Silently one response.
2. **`IResult` return types with no `Produces`.** Documents an operation with no
   response schema at all.
3. **`Produces` left behind after a refactor.** The classic lie.
4. **No `operationId`.** Generated method names change with your routes.
5. **Duplicate `operationId`.** Generation fails or silently drops an operation.
6. **Error responses undeclared.** Clients get untyped exceptions for your
   best-designed errors.
7. **Inline error schemas.** Fourteen `ProblemDetails` classes in the client.
8. **Examples that no longer match the schema.** Worse than no example.
9. **A `BindAsync` type in the signature.** Appears as nothing; needs explicit
   metadata.

## 10. The interview answer

> *"How do you keep API documentation accurate?"*

By making as much of it as possible something the compiler maintains. In minimal
APIs that means `Results<Ok<T>, NotFound, ValidationProblem>` return types rather
than `IResult` plus `Produces` attributes: the union contributes its own response
metadata, so changing what an endpoint returns is a compile error rather than a
documentation bug. Beyond that, treat the OpenAPI document as an interface
definition rather than a web page, because generated clients consume it —
`operationId`s become method names, so they must be explicit, stable and unique,
and every error response must be declared and `$ref` a shared `ProblemDetails`
schema, or clients get untyped exceptions. Then lint the document in CI for
missing or duplicate `operationId`s and undeclared statuses, and back it with
contract tests that exercise every declared response, so a declaration that
cannot happen fails the build.

## 11. Check yourself

1. What does an OpenAPI generator actually read, and what does it never do?
2. Name the two ways response metadata gets onto an endpoint, and which one
   drifts.
3. Why is `GetMetadata<IProducesResponseTypeMetadata>()` usually a bug?
4. What becomes of `operationId` in a generated client?
5. What happens when two operations share an `operationId`?
6. What does a generated client typically do with an undeclared status code?
7. Why does `$ref` on the error schema matter to a consumer?
8. How do you determine at runtime whether a property was declared `string?`?
9. What does `deprecated: true` do in a client's build, and why is that good?
10. Why does a `BindAsync` parameter document badly?
11. Give four checks a document lint should make.
12. What can a lint *not* detect, and what technique covers that gap?

