using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public record SeedDto(string Id, string Species, string Variety, int Year, int GerminationPercent);

public static class V3DA06Catalogue
{
    public static readonly List<SeedDto> Seeds =
    [
        new("SB-0001", "wheat", "Maris Widgeon", 2019, 92),
        new("SB-0002", "barley", "Golden Promise", 2021, 88),
        new("SB-0003", "rye", "Petkus", 2020, 79),
    ];

    public static SeedDto? Find(string id) => Seeds.FirstOrDefault(s => s.Id == id);
}

public class Ex1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var seeds = app.MapGroup("/v3da06/seeds");

        seeds.MapGet("/", ListSeeds)
            .WithName("listSeeds")
            .WithSummary("List accessions")
            .WithDescription("Every accession in the bank, id ascending.")
            .WithTags("seeds")
            .Produces<SeedDto[]>(200);

        // No Produces call: the union contributes 200 and 404 by itself, and the
        // compiler keeps that true.
        seeds.MapGet("/{id}", GetSeed)
            .WithName("getSeed")
            .WithSummary("Fetch one accession")
            .WithTags("seeds");

        app.MapGet("/v3da06/meta/{name}", Describe).WithTags("v3da06");
    }

    private static Ok<List<SeedDto>> ListSeeds() =>
        TypedResults.Ok(V3DA06Catalogue.Seeds.OrderBy(s => s.Id, StringComparer.Ordinal).ToList());

    private static Results<Ok<SeedDto>, NotFound> GetSeed(string id)
    {
        var seed = V3DA06Catalogue.Find(id);

        return seed is null ? TypedResults.NotFound() : TypedResults.Ok(seed);
    }

    private static IResult Describe(string name, EndpointDataSource endpoints)
    {
        var endpoint = endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .FirstOrDefault(e =>
                e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName == name);

        if (endpoint is null)
        {
            return TypedResults.NotFound();
        }

        return TypedResults.Ok(new
        {
            name,
            path = endpoint.RoutePattern.RawText,
            methods = endpoint.Metadata.GetMetadata<HttpMethodMetadata>()?.HttpMethods.ToList()
                      ?? [],
            summary = endpoint.Metadata.GetMetadata<IEndpointSummaryMetadata>()?.Summary,
            tags = endpoint.Metadata.GetMetadata<ITagsMetadata>()?.Tags.ToList() ?? [],

            // Ordered, not singular: GetMetadata would report one code.
            statusCodes = endpoint.Metadata
                .GetOrderedMetadata<IProducesResponseTypeMetadata>()
                .Select(m => m.StatusCode)
                .Distinct()
                .Order()
                .ToList(),
        });
    }
}

