using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public class Ex2 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da06/lint/report", Report).WithTags("v3da06");
    }

    private static IResult Report(EndpointDataSource endpoints)
    {
        var findings = endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .Select(e => (Endpoint: e,
                Name: e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName))
            .Where(x => x.Name is not null
                        && x.Name.StartsWith("lint", StringComparison.Ordinal))
            .OrderBy(x => x.Name, StringComparer.Ordinal)
            .Select(x =>
            {
                var declared = x.Endpoint.Metadata
                    .GetOrderedMetadata<IProducesResponseTypeMetadata>()
                    .Select(m => m.StatusCode)
                    .Distinct()
                    .Order()
                    .ToArray();

                var expected = V3DA06Expected.For(x.Name!);

                // A client with no handling for a case that happens.
                var undeclared = expected.Except(declared).Order().ToArray();

                // A client with handling for a case that never happens.
                var impossible = declared.Except(expected).Order().ToArray();

                return new
                {
                    name = x.Name!,
                    declared,
                    expected,
                    undeclared,
                    impossible,
                    ok = undeclared.Length == 0 && impossible.Length == 0,
                };
            })
            .ToList();

        return TypedResults.Ok(new
        {
            findings,
            failures = findings.Count(f => !f.ok),
        });
    }
}

