using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public record SeedRequest(string Species, string Variety, int Year);

public class Ex3 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var accepts = app.MapGroup("/v3da06/accepts").WithTags("v3da06");

        // Inferred: type and content type are both visible in the signature.
        accepts.MapPost("/json", (SeedRequest body) => TypedResults.Ok(new { ok = true }))
            .WithName("acceptsJson");

        accepts.MapPost("/optional", (SeedRequest? body) =>
                TypedResults.Ok(new { received = body is not null }))
            .WithName("acceptsOptional");

        // A Stream tells the framework nothing; say what the bytes are.
        accepts.MapPost("/raw", async (Stream body) =>
            {
                using var memory = new MemoryStream();
                await body.CopyToAsync(memory);

                return TypedResults.Ok(new { length = memory.Length });
            })
            .WithName("acceptsRaw")
            .Accepts<byte[]>("application/octet-stream");

        // BindAsync is invisible to documentation: pay it back by hand.
        accepts.MapPost("/bound", (ImportContext context) =>
                TypedResults.Ok(new { source = context.Source }))
            .WithName("acceptsBound")
            .Accepts<ImportContext>("application/json");

        accepts.MapGet("/report", Report);
    }

    private static IResult Report(EndpointDataSource endpoints)
    {
        var operations = endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .Select(e => (Endpoint: e,
                Name: e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName))
            .Where(x => x.Name is not null
                        && x.Name.StartsWith("accepts", StringComparison.Ordinal))
            .OrderBy(x => x.Name, StringComparer.Ordinal)
            .Select(x =>
            {
                var accepts = x.Endpoint.Metadata.GetMetadata<IAcceptsMetadata>();

                return new
                {
                    name = x.Name!,
                    contentTypes = accepts?.ContentTypes.Order(StringComparer.Ordinal).ToArray()
                                   ?? [],
                    requestType = accepts?.RequestType?.Name,
                    optional = accepts?.IsOptional ?? false,
                };
            })
            .ToList();

        return TypedResults.Ok(new { operations });
    }
}

