using System.Reflection;
using System.Text.Json;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public static class V3DA06Schema
{
    public static Dictionary<string, object?> Of(Type type)
    {
        var context = new NullabilityInfoContext();
        var properties = new Dictionary<string, object?>();
        var required = new List<string>();

        foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        {
            var name = JsonNamingPolicy.CamelCase.ConvertName(property.Name);

            var underlying = Nullable.GetUnderlyingType(property.PropertyType);

            // string? and string are the same runtime type: only the compile-time
            // metadata separates them, and this is how to read it.
            var isNullable = underlying is not null
                || context.Create(property).ReadState == NullabilityState.Nullable;

            properties[name] = Map(underlying ?? property.PropertyType);

            if (!isNullable)
            {
                required.Add(name);
            }
        }

        return new Dictionary<string, object?>
        {
            ["type"] = "object",
            ["properties"] = properties,
            ["required"] = required.Order(StringComparer.Ordinal).ToList(),
        };
    }

    private static Dictionary<string, object?> Map(Type type)
    {
        if (type == typeof(string))
        {
            return new Dictionary<string, object?> { ["type"] = "string" };
        }

        if (type == typeof(bool))
        {
            return new Dictionary<string, object?> { ["type"] = "boolean" };
        }

        if (type == typeof(int))
        {
            return new Dictionary<string, object?> { ["type"] = "integer", ["format"] = "int32" };
        }

        if (type == typeof(long))
        {
            return new Dictionary<string, object?> { ["type"] = "integer", ["format"] = "int64" };
        }

        if (type == typeof(decimal) || type == typeof(double))
        {
            return new Dictionary<string, object?> { ["type"] = "number", ["format"] = "double" };
        }

        if (type == typeof(DateOnly))
        {
            return new Dictionary<string, object?> { ["type"] = "string", ["format"] = "date" };
        }

        if (type == typeof(DateTimeOffset) || type == typeof(DateTime))
        {
            return new Dictionary<string, object?>
            {
                ["type"] = "string",
                ["format"] = "date-time",
            };
        }

        var element = ElementOf(type);
        if (element is not null)
        {
            return new Dictionary<string, object?>
            {
                ["type"] = "array",
                ["items"] = Map(element),
            };
        }

        return new Dictionary<string, object?> { ["type"] = "object" };
    }

    private static Type? ElementOf(Type type)
    {
        if (type.IsArray)
        {
            return type.GetElementType();
        }

        if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(List<>))
        {
            return type.GetGenericArguments()[0];
        }

        return null;
    }
}

public class Ex4 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da06/schema/{type}", GetSchema).WithTags("v3da06");
    }

    private static IResult GetSchema(string type) => type switch
    {
        "seed" => TypedResults.Ok(V3DA06Schema.Of(typeof(SeedDto))),
        "request" => TypedResults.Ok(V3DA06Schema.Of(typeof(SeedRequest))),
        "germination" => TypedResults.Ok(V3DA06Schema.Of(typeof(GerminationTest))),
        _ => TypedResults.NotFound(),
    };
}

