using System.Text.RegularExpressions;
using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;
using Microsoft.AspNetCore.WebUtilities;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public class Ex5 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da06/openapi.json", Document).WithTags("v3da06");
    }

    private static IResult Document(EndpointDataSource endpoints)
    {
        var schemas = new Dictionary<string, object?>();
        var paths = new SortedDictionary<string, object?>(StringComparer.Ordinal);

        var tagged = endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .Where(e => e.Metadata.GetMetadata<ITagsMetadata>()?.Tags.Contains("seeds") == true);

        foreach (var group in tagged.GroupBy(e => e.RoutePattern.RawText!))
        {
            var operations = new SortedDictionary<string, object?>(StringComparer.Ordinal);

            foreach (var endpoint in group)
            {
                var methods = endpoint.Metadata.GetMetadata<HttpMethodMetadata>()?.HttpMethods
                              ?? ["GET"];

                foreach (var method in methods)
                {
                    operations[method.ToLowerInvariant()] = Operation(endpoint, group.Key, schemas);
                }
            }

            paths[group.Key] = operations;
        }

        return TypedResults.Ok(new Dictionary<string, object?>
        {
            ["openapi"] = "3.0.1",
            ["info"] = new Dictionary<string, object?>
            {
                ["title"] = "Seed bank",
                ["version"] = "1.0.0",
            },
            ["paths"] = paths,
            ["components"] = new Dictionary<string, object?> { ["schemas"] = schemas },
        });
    }

    private static Dictionary<string, object?> Operation(
        RouteEndpoint endpoint, string template, Dictionary<string, object?> schemas)
    {
        var responses = new SortedDictionary<string, object?>(
            Comparer<string>.Create((a, b) => int.Parse(a).CompareTo(int.Parse(b))));

        foreach (var declared in endpoint.Metadata
                     .GetOrderedMetadata<IProducesResponseTypeMetadata>())
        {
            var response = new Dictionary<string, object?>
            {
                // Required by the specification on every response object.
                ["description"] = ReasonPhrases.GetReasonPhrase(declared.StatusCode),
            };

            if (declared.Type is { } type && type != typeof(void))
            {
                response["content"] = new Dictionary<string, object?>
                {
                    ["application/json"] = new Dictionary<string, object?>
                    {
                        ["schema"] = SchemaRef(type, schemas),
                    },
                };
            }

            responses[declared.StatusCode.ToString()] = response;
        }

        return new Dictionary<string, object?>
        {
            ["operationId"] = endpoint.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName,
            ["tags"] = endpoint.Metadata.GetMetadata<ITagsMetadata>()?.Tags.ToList() ?? [],
            ["summary"] = endpoint.Metadata.GetMetadata<IEndpointSummaryMetadata>()?.Summary,
            ["parameters"] = Parameters(template),
            ["responses"] = responses,
        };
    }

    private static List<object> Parameters(string template) =>
        Regex.Matches(template, @"\{(\w+)")
            .Select(m => (object)new Dictionary<string, object?>
            {
                ["name"] = m.Groups[1].Value,
                ["in"] = "path",
                ["required"] = true,
                ["schema"] = new Dictionary<string, object?> { ["type"] = "string" },
            })
            .ToList();

    // Emitted once into components, referenced everywhere else: one class in the
    // generated client instead of one per operation.
    private static Dictionary<string, object?> SchemaRef(
        Type type, Dictionary<string, object?> schemas)
    {
        if (type.IsArray || (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(List<>)))
        {
            var element = type.IsArray ? type.GetElementType()! : type.GetGenericArguments()[0];

            return new Dictionary<string, object?>
            {
                ["type"] = "array",
                ["items"] = SchemaRef(element, schemas),
            };
        }

        schemas.TryAdd(type.Name, V3DA06Schema.Of(type));

        return new Dictionary<string, object?> { ["$ref"] = $"#/components/schemas/{type.Name}" };
    }
}

