// v3da06_openapi_clients / ex6 - reference solution (author only, used by `dojo verify`).

using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public class Ex6 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da06/names/report", Report).WithTags("v3da06");
    }

    private static IResult Report(EndpointDataSource endpoints)
    {
        var candidates = endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .Where(e => e.RoutePattern.RawText!.StartsWith("/v3da06/names/", StringComparison.Ordinal)
                        && !e.RoutePattern.RawText!.EndsWith("/report", StringComparison.Ordinal))
            .Select(e => new
            {
                Path = e.RoutePattern.RawText!,
                Method = e.Metadata.GetMetadata<HttpMethodMetadata>()?.HttpMethods.First() ?? "GET",
                Name = e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName,
            })
            .ToList();

        var missing = candidates
            .Where(c => string.IsNullOrEmpty(c.Name))
            .Select(c => c.Path)
            .Order(StringComparer.Ordinal)
            .ToList();

        var duplicates = candidates
            .Where(c => !string.IsNullOrEmpty(c.Name))
            .GroupBy(c => c.Name!, StringComparer.Ordinal)
            .Where(g => g.Count() > 1)
            .OrderBy(g => g.Key, StringComparer.Ordinal)
            .Select(g => new
            {
                operationId = g.Key,
                paths = g.Select(c => c.Path).Order(StringComparer.Ordinal).ToList(),
            })
            .ToList();

        // What a generator invents when nobody chose - derived from the route,
        // and therefore changing whenever the route does.
        var synthesised = candidates
            .Where(c => string.IsNullOrEmpty(c.Name))
            .OrderBy(c => c.Path, StringComparer.Ordinal)
            .Select(c => new
            {
                path = c.Path,
                method = c.Method,
                operationId = Synthesise(c.Method, c.Path),
            })
            .ToList();

        return TypedResults.Ok(new
        {
            missing,
            duplicates,
            synthesised,
            ok = missing.Count == 0 && duplicates.Count == 0,
        });
    }

    private static string Synthesise(string method, string path)
    {
        var segments = path
            .Split('/', StringSplitOptions.RemoveEmptyEntries)
            .Select(s => s.Replace("{", string.Empty).Replace("}", string.Empty).Replace("-", " "))
            .SelectMany(s => s.Split(' ', StringSplitOptions.RemoveEmptyEntries))
            .Select(s => char.ToUpperInvariant(s[0]) + s[1..]);

        return method.ToLowerInvariant() + string.Concat(segments);
    }
}

