            var operation = new Dictionary<string, object?> { ["operationId"] = name };

            if (endpoint.Metadata.GetMetadata<V3DA06Deprecated>() is { } deprecated)
            {
                // Omitted entirely when false: the specification's default is
                // false, and "deprecated": false everywhere is diff noise.
                operation["deprecated"] = true;
                operation["x-deprecation-note"] = deprecated.Note;
                operation["x-sunset"] = deprecated.Sunset;
