    private static IResult CheckExamples(EndpointDataSource endpoints)
    {
        var checks = new List<object>();
        var ok = true;

        foreach (var endpoint in Operations(endpoints))
        {
            if (endpoint.Metadata.GetMetadata<V3DA06Example>() is not { } example)
            {
