            var name = endpoint.Metadata.GetMetadata<IEndpointNameMetadata>()!.EndpointName!;
            var schema = V3DA06Schema.Of(typeof(SeedRequest));
            var problems = Validate(example.Value, schema);

            ok &= problems.Count == 0;

            checks.Add(new { operationId = name, valid = problems.Count == 0, problems });
        }

        return TypedResults.Ok(new { checks, ok });
    }

    private static List<string> Validate(object example, Dictionary<string, object?> schema)
    {
        var problems = new List<string>();

        // Same options the application serialises with, or the casing disagrees
        // and every property looks undeclared.
        var json = JsonSerializer.SerializeToNode(example, example.GetType(), Json)!.AsObject();

        var declared = ((Dictionary<string, object?>)schema["properties"]!).Keys.ToHashSet(
            StringComparer.Ordinal);

        foreach (var required in (List<string>)schema["required"]!)
        {
            if (!json.ContainsKey(required) || json[required] is null)
            {
                problems.Add($"missing required property: {required}");
            }
        }

        foreach (var property in json)
        {
            if (!declared.Contains(property.Key))
            {
                problems.Add($"undeclared property: {property.Key}");
            }
        }

        return problems;
    }

    private static IEnumerable<RouteEndpoint> Operations(EndpointDataSource endpoints) =>
        endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .Where(e => e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName is
                "listVarieties" or "listLegacyVarieties" or "createVariety");
}

