// v3da06_openapi_clients / ex8 - reference solution (author only, used by `dojo verify`).

using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public class Ex8 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var errors = app.MapGroup("/v3da06/errors").WithTags("v3da06-errors");

        errors.MapGet("/accessions", () => TypedResults.Ok(V3DA06Catalogue.Seeds))
            .WithName("listAccessions");

        errors.MapGet("/accessions/{id}", GetAccession).WithName("getAccession");
        errors.MapPost("/accessions", CreateAccession).WithName("createAccession");
        errors.MapDelete("/accessions/{id}", DeleteAccession).WithName("deleteAccession");

        errors.MapGet("/document", Document);
        errors.MapGet("/audit", Audit);
    }

    private static Results<Ok<SeedDto>, ProblemHttpResult> GetAccession(string id)
    {
        var seed = V3DA06Catalogue.Find(id);

        return seed is null
            ? TypedResults.Problem(title: "No such accession", statusCode: 404)
            : TypedResults.Ok(seed);
    }

    private static Results<Created<SeedDto>, ValidationProblem> CreateAccession(SeedRequest body)
    {
        var problems = new Dictionary<string, string[]>();

        if (string.IsNullOrWhiteSpace(body.Species))
        {
            problems["species"] = ["Required."];
        }

        if (string.IsNullOrWhiteSpace(body.Variety))
        {
            problems["variety"] = ["Required."];
        }

        if (body.Year is < 1900 or > 2100)
        {
            problems["year"] = ["Between 1900 and 2100."];
        }

        if (problems.Count > 0)
        {
            return TypedResults.ValidationProblem(problems, statusCode: 422);
        }

        var dto = new SeedDto($"SB-{V3DA06Catalogue.Seeds.Count + 1:0000}",
            body.Species, body.Variety, body.Year, 0);

        return TypedResults.Created($"/v3da06/errors/accessions/{dto.Id}", dto);
    }

    private static Results<NoContent, ProblemHttpResult> DeleteAccession(string id)
    {
        if (V3DA06Catalogue.Find(id) is null)
        {
            return TypedResults.Problem(title: "No such accession", statusCode: 404);
        }

        if (V3DA06Tests.HasTests(id))
        {
            return TypedResults.Problem(title: "Germination tests recorded", statusCode: 409);
        }

        return TypedResults.NoContent();
    }

    private static IResult Document(EndpointDataSource endpoints)
    {
        // Components first, so no operation can reference something absent.
        var schemas = new Dictionary<string, object?>
        {
            ["ProblemDetails"] = ProblemSchema(false),
            ["ValidationProblemDetails"] = ProblemSchema(true),
        };

        var responses = new Dictionary<string, object?>
        {
            ["NotFound"] = ErrorResponse("Not Found", "ProblemDetails"),
            ["Conflict"] = ErrorResponse("Conflict", "ProblemDetails"),
            ["ValidationFailed"] =
                ErrorResponse("Unprocessable Content", "ValidationProblemDetails"),
        };

        var operations = new SortedDictionary<string, object?>(StringComparer.Ordinal);

        foreach (var endpoint in Named(endpoints))
        {
            var name = endpoint.Metadata.GetMetadata<IEndpointNameMetadata>()!.EndpointName!;
            var declared = endpoint.Metadata
                .GetOrderedMetadata<IProducesResponseTypeMetadata>()
                .Select(m => m.StatusCode)
                .Distinct()
                .Order()
                .ToList();

            var operationResponses = new SortedDictionary<string, object?>(StringComparer.Ordinal);

            foreach (var status in declared)
            {
                // A $ref response object holds only the $ref: sibling keys are
                // ignored in OpenAPI 3.0.
                operationResponses[status.ToString()] = status switch
                {
                    404 => Ref("responses", "NotFound"),
                    409 => Ref("responses", "Conflict"),
                    422 => Ref("responses", "ValidationFailed"),
                    _ => new Dictionary<string, object?> { ["description"] = "OK" },
                };
            }

            operations[name] = new Dictionary<string, object?>
            {
                ["operationId"] = name,
                ["responses"] = operationResponses,
            };
        }

        return TypedResults.Ok(new Dictionary<string, object?>
        {
            ["openapi"] = "3.0.1",
            ["operations"] = operations,
            ["components"] = new Dictionary<string, object?>
            {
                ["schemas"] = schemas,
                ["responses"] = responses,
            },
        });
    }

    private static IResult Audit(EndpointDataSource endpoints)
    {
        var withoutErrors = new List<string>();
        var sharedRefs = 0;

        foreach (var endpoint in Named(endpoints))
        {
            var name = endpoint.Metadata.GetMetadata<IEndpointNameMetadata>()!.EndpointName!;
            var failures = endpoint.Metadata
                .GetOrderedMetadata<IProducesResponseTypeMetadata>()
                .Select(m => m.StatusCode)
                .Where(s => s >= 400)
                .Distinct()
                .ToList();

            if (failures.Count == 0)
            {
                // Correctly has none: reported, but not a failure.
                withoutErrors.Add(name);
            }

            sharedRefs += failures.Count;
        }

        return TypedResults.Ok(new
        {
            inlineErrorSchemas = 0,
            sharedRefs,
            operationsWithNoErrorDocs = withoutErrors.Order(StringComparer.Ordinal).ToList(),
            ok = true,
        });
    }

    private static Dictionary<string, object?> ProblemSchema(bool validation)
    {
        var properties = new Dictionary<string, object?>
        {
            ["type"] = new Dictionary<string, object?> { ["type"] = "string" },
            ["title"] = new Dictionary<string, object?> { ["type"] = "string" },
            ["status"] = new Dictionary<string, object?>
            {
                ["type"] = "integer",
                ["format"] = "int32",
            },
            ["detail"] = new Dictionary<string, object?> { ["type"] = "string" },
            ["instance"] = new Dictionary<string, object?> { ["type"] = "string" },
            ["traceId"] = new Dictionary<string, object?> { ["type"] = "string" },
        };

        var required = new List<string> { "status", "title" };

        if (validation)
        {
            properties["errors"] = new Dictionary<string, object?>
            {
                ["type"] = "object",
                ["additionalProperties"] = new Dictionary<string, object?>
                {
                    ["type"] = "array",
                    ["items"] = new Dictionary<string, object?> { ["type"] = "string" },
                },
            };

            required.Add("errors");
        }

        return new Dictionary<string, object?>
        {
            ["type"] = "object",
            ["properties"] = properties,
            ["required"] = required.Order(StringComparer.Ordinal).ToList(),
        };
    }

    private static Dictionary<string, object?> ErrorResponse(string description, string schema) =>
        new()
        {
            ["description"] = description,
            ["content"] = new Dictionary<string, object?>
            {
                ["application/problem+json"] = new Dictionary<string, object?>
                {
                    ["schema"] = Ref("schemas", schema),
                },
            },
        };

    private static Dictionary<string, object?> Ref(string section, string name) =>
        new() { ["$ref"] = $"#/components/{section}/{name}" };

    private static IEnumerable<RouteEndpoint> Named(EndpointDataSource endpoints) =>
        endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .Where(e => e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName is
                "listAccessions" or "getAccession" or "createAccession" or "deleteAccession");
}

