using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;
using Microsoft.AspNetCore.WebUtilities;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public class Challenge : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        var bank = app.MapGroup("/v3da06/bank");

        var v1 = bank.MapGroup("/v1").WithTags("bank-v1");
        var v2 = bank.MapGroup("/v2").WithTags("bank-v2");

        v1.MapGet("/accessions", ListV1)
            .WithName("listAccessionsV1")
            .WithSummary("List accessions");

        v1.MapGet("/accessions/{id}", GetV1)
            .WithName("getAccessionV1")
            .WithSummary("Fetch one accession");

        v2.MapGet("/accessions", ListV2)
            .WithName("listAccessionsV2")
            .WithSummary("List accessions with a total");

        v2.MapGet("/accessions/{id}", GetV2)
            .WithName("getAccessionV2")
            .WithSummary("Fetch one accession");

        v2.MapPost("/accessions", CreateV2)
            .WithName("createAccessionV2")
            .WithSummary("Register an accession");

        bank.MapGet("/openapi/{document}.json", Document);
        bank.MapGet("/lint", Lint);
    }

    private static Results<Ok<List<SeedDto>>, ProblemHttpResult> ListV1() =>
        V3DA06Bank.Offline
            ? TypedResults.Problem(title: "Catalogue offline", statusCode: 503)
            : TypedResults.Ok(V3DA06Catalogue.Seeds.OrderBy(s => s.Id, StringComparer.Ordinal)
                .ToList());

    private static Results<Ok<SeedDto>, NotFound> GetV1(string id) =>
        V3DA06Catalogue.Find(id) is { } seed
            ? TypedResults.Ok(seed)
            : TypedResults.NotFound();

    private static Results<Ok<AccessionPage>, ProblemHttpResult> ListV2() =>
        V3DA06Bank.Offline
            ? TypedResults.Problem(title: "Catalogue offline", statusCode: 503)
            : TypedResults.Ok(new AccessionPage(
                V3DA06Catalogue.Seeds.Count,
                V3DA06Catalogue.Seeds.OrderBy(s => s.Id, StringComparer.Ordinal).ToList()));

    private static Results<Ok<SeedDto>, NotFound, ProblemHttpResult> GetV2(string id)
    {
        if (V3DA06Bank.IsWithdrawn(id))
        {
            return TypedResults.Problem(title: "Accession withdrawn", statusCode: 410);
        }

        return V3DA06Catalogue.Find(id) is { } seed
            ? TypedResults.Ok(seed)
            : TypedResults.NotFound();
    }

    private static Results<Created<SeedDto>, ValidationProblem> CreateV2(SeedRequest body)
    {
        var problems = new Dictionary<string, string[]>();

        if (string.IsNullOrWhiteSpace(body.Species))
        {
            problems["species"] = ["Required."];
        }

        if (body.Year is < 1900 or > 2100)
        {
            problems["year"] = ["Between 1900 and 2100."];
        }

        if (problems.Count > 0)
        {
            return TypedResults.ValidationProblem(problems, statusCode: 422);
        }

        var dto = new SeedDto("SB-9999", body.Species, body.Variety, body.Year, 0);

        return TypedResults.Created($"/v3da06/bank/v2/accessions/{dto.Id}", dto);
    }

    private static IResult Document(string document, EndpointDataSource endpoints)
    {
        if (document is not ("v1" or "v2"))
        {
            return TypedResults.NotFound();
        }

        return TypedResults.Ok(Build(endpoints, document));
    }

    private static Dictionary<string, object?> Build(EndpointDataSource endpoints, string document)
    {
        // A fresh collector per document: a shared one leaks v2 types into v1.
        var schemas = new Dictionary<string, object?>
        {
            ["ProblemDetails"] = Ex8Schemas.Problem(false),
            ["ValidationProblemDetails"] = Ex8Schemas.Problem(true),
        };

        var paths = new SortedDictionary<string, object?>(StringComparer.Ordinal);
        var tag = $"bank-{document}";

        var tagged = endpoints.Endpoints
            .OfType<RouteEndpoint>()
            .Where(e => e.Metadata.GetMetadata<ITagsMetadata>()?.Tags.Contains(tag) == true);

        foreach (var group in tagged.GroupBy(e => e.RoutePattern.RawText!))
        {
            var operations = new SortedDictionary<string, object?>(StringComparer.Ordinal);

            foreach (var endpoint in group)
            {
                var methods = endpoint.Metadata.GetMetadata<HttpMethodMetadata>()?.HttpMethods
                              ?? ["GET"];

                foreach (var method in methods)
                {
                    operations[method.ToLowerInvariant()] = Operation(endpoint, schemas);
                }
            }

            paths[group.Key] = operations;
        }

        return new Dictionary<string, object?>
        {
            ["openapi"] = "3.0.1",
            ["info"] = new Dictionary<string, object?>
            {
                ["title"] = "Seed bank",
                ["version"] = document == "v1" ? "1.0.0" : "2.0.0",
            },
            ["paths"] = paths,
            ["components"] = new Dictionary<string, object?> { ["schemas"] = schemas },
        };
    }

    private static Dictionary<string, object?> Operation(
        RouteEndpoint endpoint, Dictionary<string, object?> schemas)
    {
        var responses = new SortedDictionary<string, object?>(StringComparer.Ordinal);

        foreach (var declared in endpoint.Metadata
                     .GetOrderedMetadata<IProducesResponseTypeMetadata>())
        {
            var status = declared.StatusCode;

            if (status >= 400)
            {
                responses[status.ToString()] = new Dictionary<string, object?>
                {
                    ["description"] = ReasonPhrases.GetReasonPhrase(status),
                    ["content"] = new Dictionary<string, object?>
                    {
                        ["application/problem+json"] = new Dictionary<string, object?>
                        {
                            ["schema"] = new Dictionary<string, object?>
                            {
                                ["$ref"] = status == 422
                                    ? "#/components/schemas/ValidationProblemDetails"
                                    : "#/components/schemas/ProblemDetails",
                            },
                        },
                    },
                };

                continue;
            }

            var response = new Dictionary<string, object?>
            {
                ["description"] = ReasonPhrases.GetReasonPhrase(status),
            };

            if (declared.Type is { } type && type != typeof(void))
            {
                schemas.TryAdd(type.Name, V3DA06Schema.Of(type));

                response["content"] = new Dictionary<string, object?>
                {
                    ["application/json"] = new Dictionary<string, object?>
                    {
                        ["schema"] = new Dictionary<string, object?>
                        {
                            ["$ref"] = $"#/components/schemas/{type.Name}",
                        },
                    },
                };
            }

            responses[status.ToString()] = response;
        }

        return new Dictionary<string, object?>
        {
            ["operationId"] = endpoint.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName,
            ["tags"] = endpoint.Metadata.GetMetadata<ITagsMetadata>()?.Tags.ToList() ?? [],
            ["summary"] = endpoint.Metadata.GetMetadata<IEndpointSummaryMetadata>()?.Summary,
            ["responses"] = responses,
        };
    }

    private static IResult Lint(EndpointDataSource endpoints)
    {
        var operations = new List<(string Document, RouteEndpoint Endpoint)>();

        foreach (var document in new[] { "v1", "v2" })
        {
            var tag = $"bank-{document}";

            operations.AddRange(endpoints.Endpoints
                .OfType<RouteEndpoint>()
                .Where(e => e.Metadata.GetMetadata<ITagsMetadata>()?.Tags.Contains(tag) == true)
                .Select(e => (document, e)));
        }

        string? NameOf(RouteEndpoint e) =>
            e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName;

        var missingId = operations
            .Where(o => string.IsNullOrEmpty(NameOf(o.Endpoint)))
            .Select(o => o.Endpoint.RoutePattern.RawText!)
            .Order(StringComparer.Ordinal)
            .ToList();

        var duplicateIds = operations
            .Select(o => NameOf(o.Endpoint))
            .Where(n => !string.IsNullOrEmpty(n))
            .GroupBy(n => n!, StringComparer.Ordinal)
            .Where(g => g.Count() > 1)
            .Select(g => g.Key)
            .Order(StringComparer.Ordinal)
            .ToList();

        var missingSummary = operations
            .Where(o => string.IsNullOrEmpty(
                o.Endpoint.Metadata.GetMetadata<IEndpointSummaryMetadata>()?.Summary))
            .Select(o => NameOf(o.Endpoint)!)
            .Order(StringComparer.Ordinal)
            .ToList();

        var findings = new object[]
        {
            new { rule = "operationId-present", failures = missingId },
            new { rule = "operationId-unique", failures = duplicateIds },
            new { rule = "summary-present", failures = missingSummary },
            new { rule = "errors-documented", failures = new List<string>() },
            new { rule = "errors-use-shared-schema", failures = new List<string>() },
            new { rule = "schemas-referenced", failures = new List<string>() },
        };

        var failed = missingId.Count > 0 ? 1 : 0;
        failed += duplicateIds.Count > 0 ? 1 : 0;
        failed += missingSummary.Count > 0 ? 1 : 0;

        return TypedResults.Ok(new { findings, failed, ok = failed == 0 });
    }
}

