// v3da06_openapi_clients / review1 - reference solution (author only, used by `dojo verify`).

using System.Text.Json;
using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;

namespace DotnetDojo.Api.V3DA06_OpenApiClients;

public class Review1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3da06/drift/probe", Probe).WithTags("v3da06");
    }

    private static async Task<IResult> Probe(
        EndpointDataSource endpoints, V3DA06Prober prober, CancellationToken cancellation)
    {
        var findings = new List<object>();

        foreach (var endpoint in endpoints.Endpoints
                     .OfType<RouteEndpoint>()
                     .Select(e => (Endpoint: e,
                         Name: e.Metadata.GetMetadata<IEndpointNameMetadata>()?.EndpointName))
                     .Where(x => x.Name is not null
                                 && x.Name.StartsWith("drift", StringComparison.Ordinal))
                     .OrderBy(x => x.Name, StringComparer.Ordinal))
        {
            var declaredMetadata = endpoint.Endpoint.Metadata
                .GetOrderedMetadata<IProducesResponseTypeMetadata>()
                .ToList();

            var declared = declaredMetadata
                .Select(m => m.StatusCode)
                .Distinct()
                .Order()
                .ToArray();

            var observed = new SortedSet<int>();
            object? schemaMismatch = null;

            foreach (var path in V3DA06Probes.For(endpoint.Name!))
            {
                var (status, body) = await prober.GetAsync(path, cancellation);
                observed.Add(status);

                if (status is < 200 or > 299 || schemaMismatch is not null)
                {
                    continue;
                }

                var declaredType = declaredMetadata
                    .FirstOrDefault(m => m.StatusCode == status)?.Type;

                if (declaredType is null)
                {
                    continue;
                }

                var schema = V3DA06Schema.Of(declaredType);
                var expected = ((Dictionary<string, object?>)schema["properties"]!)
                    .Keys.ToHashSet(StringComparer.Ordinal);

                using var json = JsonDocument.Parse(body);

                var actual = json.RootElement.ValueKind == JsonValueKind.Object
                    ? json.RootElement.EnumerateObject()
                        .Select(p => p.Name)
                        .ToHashSet(StringComparer.Ordinal)
                    : [];

                var missing = expected.Except(actual).Order(StringComparer.Ordinal).ToArray();
                var extra = actual.Except(expected).Order(StringComparer.Ordinal).ToArray();

                // Right status, wrong shape: passes every status check ever
                // written, and breaks every generated client.
                if (missing.Length > 0 || extra.Length > 0)
                {
                    schemaMismatch = new
                    {
                        status,
                        declaredType = declaredType.Name,
                        missing,
                        extra,
                    };
                }
            }

            var undeclared = observed.Except(declared).Order().ToArray();
            var unobserved = declared.Except(observed).Order().ToArray();

            if (undeclared.Length == 0 && unobserved.Length == 0 && schemaMismatch is null)
            {
                continue;
            }

            findings.Add(new
            {
                operationId = endpoint.Name!,
                declared,
                observed = observed.ToArray(),
                undeclared,

                // A weak signal: either a lie or a gap in the probes, and only a
                // human can tell which.
                unobserved,
                schemaMismatch,
            });
        }

        return TypedResults.Ok(new { findings, ok = findings.Count == 0 });
    }
}
